const {test}=require('node:test');const assert=require('node:assert/strict');const vm=require('node:vm');const fs=require('node:fs');
function game(funded=true,guide=false){const elements={};const el=id=>elements[id]??=( {value:({color:'#53c9eb',c1:'#ef685a',c2:'#b88af0',ai1:'horde',ai2:'off'})[id],style:{},dataset:{},classList:{toggle(){}},clientWidth:1200,clientHeight:650,getContext(){return{};},appendChild(){},getBoundingClientRect(){return{left:0,top:0,width:id==='world'?1200:210,height:id==='world'?650:150};}});const c=vm.createContext({document:{getElementById:el,querySelectorAll(){return[];},createElement(){return el(Math.random());}},window:{addEventListener(){}},Math:Object.assign(Object.create(Math),{random:()=>.999}),requestAnimationFrame(){},alert(){},console});vm.runInContext(fs.readFileSync(require.resolve('../game.js'),'utf8'),c);if(guide)vm.runInContext(fs.readFileSync(require.resolve('../tutorial.js'),'utf8'),c);vm.runInContext('start();state.count=0;',c);if(funded)vm.runInContext('state.players.forEach(p=>{p.gold=650;p.wood=500;});',c);return code=>vm.runInContext(code,c);}
test('starts with two factions and hides enemy territory',()=>{const run=game();assert.equal(run('state.players.length'),2);assert.equal(run('state.entities.filter(e=>e.owner===0&&e.type==="worker").length'),4);assert.equal(run('visible(2080,2000)'),false);assert.equal(run('visible(250,300)'),true);});
test('lumber upgrades increase harvesting yield',()=>{const r=game();assert.ok(r(`(()=>{state.ai=999;const w=state.entities[1],p=state.players[0],t=state.resources.find(t=>t.type==='wood');w.x=t.x;w.y=t.y;w.order={kind:'gather',target:t};let before=w.cargoWood||0;tick(1);if(w.cargoWood-before!==1.5)return false;p.lumber=1;before=w.cargoWood;tick(1);return w.cargoWood-before>1.5;})()`));});
test('production consumes resources and completes real units',()=>{const r=game();assert.equal(r(`(()=>{const b=state.entities[0];train(b,'worker');tick(20.1);return state.entities.filter(e=>e.owner===0&&e.type==='worker').length;})()`),5);});
test('hero aura changes damage only inside its radius',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];entity('base',0,100,100,true);entity('base',1,2100,2100,true);state.ai=999;const a=entity('melee',1,500,500),t=entity('melee',0,510,500),h=entity('hero',0,520,500);h.order={kind:'hold'};h.cool=999;t.cool=999;tick(.01);const reduced=t.max-t.hp;h.x=1000;a.cool=0;tick(.01);const normal=t.max-t.hp-reduced;return reduced<normal&&Math.abs(reduced-normal*.7)<.001;})()`));});
test('destroying opposing stronghold wins',()=>{const r=game();assert.equal(r("state.entities.find(e=>e.owner===1&&e.type==='base').hp=0;tick(.01);state.ended"),true);});
test('pointer selection and destination command move the selected collector',()=>{const r=game();assert.ok(r(`(()=>{canvas.onpointerdown({button:0,clientX:190,clientY:385});canvas.onpointerup({button:0,clientX:190,clientY:385});if(selected.length!==1)return false;commandMode='move';canvas.onpointerdown({button:2,clientX:300,clientY:480,preventDefault(){}});const w=selected[0],x=w.x;tick(.5);return w.order.kind==='move'&&w.x>x&&commandMode===null&&orderMarker.x===300;})()`));});
test('right-click orders a group without clearing selection',()=>{const r=game();assert.ok(r(`(()=>{selected=state.entities.filter(e=>e.owner===0&&!e.building);canvas.onpointerdown({button:2,clientX:800,clientY:600,preventDefault(){}});return selected.length===4&&selected.every(e=>e.order.kind==='move');})()`));});
test('production buildings send newly trained troops to their rally point',()=>{const r=game();assert.ok(r(`(()=>{const b=entity('barracks',0,350,300,true);selected=[b];commandMode='rally';issueCommand({x:600,y:500});train(b,'melee');state.ai=999;tick(7.6);const u=state.entities.find(e=>e.owner===0&&e.type==='melee');return u.order.kind==='move'&&u.order.x===600&&u.order.y===500&&b.rally.x===600;})()`));});
test('stronghold resource rally gives new collectors a gathering order',()=>{const r=game();assert.ok(r(`(()=>{const b=state.entities[0],resource=state.resources.find(t=>t.type==='gold'&&visible(t.x,t.y));selected=[b];issueCommand(resource);train(b,'worker');state.ai=999;tick(20.1);const w=state.entities.filter(e=>e.owner===0&&e.type==='worker').at(-1);return w.order.kind==='gather'&&w.order.target===resource;})()`));});
test('gathering animation starts only at the resource and uses the right tool',()=>{const r=game();assert.ok(r(`(()=>{const w=state.entities[1],t=state.resources.find(t=>t.type==='wood');w.order={kind:'gather',target:t};w.x=t.x-100;w.y=t.y;state.ai=999;tick(.01);if(w.action)return false;w.x=t.x-20;tick(.01);return w.action.kind==='gather'&&w.action.resource==='wood'&&w.action.until>state.time;})()`));});
test('melee swings and ranged projectiles are driven by successful attacks',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];entity('base',0,100,100,true);entity('base',1,2100,2100,true);state.ai=999;const a=entity('melee',0,300,300),b=entity('melee',1,320,300),c=entity('ranged',0,280,300);b.cool=999;fog();tick(.01);return a.action.kind==='attack'&&!a.shot&&c.action.kind==='attack'&&c.shot.duration>0&&c.shot.fromX===280;})()`));});
test('watchtower fires automatically, respects cooldown and ignores allies/out-of-range enemies',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];entity('base',0,100,100,true);entity('base',1,2100,2100,true);state.ai=999;const tower=entity('tower',0,500,500,true),ally=entity('worker',0,520,500),enemy=entity('worker',1,600,500),far=entity('worker',1,1000,1000);fog();tick(.01);const hp=enemy.hp;if(hp!==enemy.max-22||ally.hp!==ally.max||far.hp!==far.max||!tower.shot)return false;tick(.1);return enemy.hp===hp;})()`));});
test('bastion splash damages nearby enemies without friendly fire',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];entity('base',0,100,100,true);entity('base',1,2100,2100,true);state.ai=999;entity('bastion',0,500,500,true);const a=entity('worker',1,600,500),b=entity('worker',1,620,500),ally=entity('worker',0,610,500);fog();tick(.01);return a.hp===a.max-60&&b.hp===b.max-24&&ally.hp===ally.max&&state.effects.some(f=>f.kind==='blast');})()`));});
test('tool effects occur on contact, expire and remain bounded',()=>{const r=game();assert.ok(r(`(()=>{state.ai=999;const w=state.entities[1],t=state.resources.find(r=>r.type==='wood');w.x=t.x-20;w.y=t.y;w.order={kind:'gather',target:t};tick(.01);if(state.effects.length)return false;tick(.41);if(!state.effects.some(f=>f.kind==='wood'))return false;w.order=null;tick(2);if(state.effects.length)return false;for(let i=0;i<100;i++)burst(200,200,'blast',0);return state.effects.length<=650;})()`));});
test('double-click selects all living friendly units of the type on the screen',()=>{const r=game();assert.ok(r(`(()=>{const far=entity('worker',0,1800,1800),dead=entity('worker',0,2000,1800);dead.hp=0;entity('melee',0,400,400);canvas.ondblclick({clientX:190,clientY:370});return selected.length===4&&!selected.includes(far)&&selected.every(e=>e.owner===0&&e.type==='worker'&&e.hp>0);})()`));});
test('shift double-click adds units and double-click groups buildings',()=>{const r=game();assert.ok(r(`(()=>{const m=entity('melee',0,500,500);selected=[m];canvas.ondblclick({clientX:190,clientY:385,shiftKey:true});if(selected.length!==5||!selected.includes(m))return false;const extra=entity('base',0,1000,500,true);canvas.ondblclick({clientX:250,clientY:300});return selected.length===2&&selected.includes(extra)&&selected.every(e=>e.type==='base'&&e.building);})()`));});
test('eight directional frames cover every compass heading',()=>{const r=game();assert.ok(r(`(()=>{state.resources=[];state.mountains=[];state.plateaus=[];state.rivers=[];const seen=new Set();for(let i=0;i<8;i++){const w=state.entities[1];w.x=500;w.y=500;move(w,500+Math.cos(i*Math.PI/4)*100,500+Math.sin(i*Math.PI/4)*100,.01);seen.add(directionFrame(w.facing));}return seen.size===8&&new Set(directionFrames.map(f=>f.name)).size===8;})()`));});
test('right-click attack commands mark an enemy red',()=>{const r=game();assert.ok(r(`(()=>{const w=state.entities[1],enemy=entity('worker',1,300,400);selected=[w];fog();canvas.onpointerdown({button:2,clientX:300,clientY:385,preventDefault(){}});return w.order.kind==='attack'&&w.order.target===enemy&&orderMarker.kind==='attack';})()`));});
test('wall construction snaps to grid, charges resources and permits adjacent segments',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];selected=[entity('worker',0,200,200)];state.resources=[];state.visible.fill(1);const before=state.players[0].wood;if(!build('wall',300,300)||!build('wall',332,300))return false;const walls=state.entities.filter(e=>e.type==='wall');return walls[0].x===304&&walls[1].x===336&&state.players[0].wood===before-35&&walls.every(w=>w.construction.left===12.5)&&state.wallVersion===0;})()`));});
test('ground units route around walls without crossing them while flying units pass over',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[];state.mountains=[];state.plateaus=[];state.rivers=[];for(let y=304;y<=400;y+=32)entity('wall',0,304,y,true);const ground=entity('worker',0,230,352),air=entity('air',0,230,352);let crossed=false;for(let i=0;i<350;i++){state.time+=.05;move(ground,420,352,.05);move(air,420,352,.05);if(wallAt(ground.x,ground.y,ground.size))crossed=true;}return !crossed&&Math.hypot(ground.x-420,ground.y-352)<6&&Math.hypot(air.x-420,air.y-352)<6;})()`));});
test('destroyed walls invalidate path caches and disappear from collision',()=>{const r=game();assert.ok(r(`(()=>{const wall=entity('wall',0,700,700,true);state.blockCache.test=new Set();wall.hp=0;state.ai=999;tick(.01);return !wallAt(700,700)&&state.wallVersion===1&&!state.blockCache.test;})()`));});
test('construction requires a selected worker and pauses without a nearby builder',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[];state.visible.fill(1);if(build('barracks',500,500))return false;const w=entity('worker',0,100,100);selected=[w];build('barracks',500,500);const b=state.entities[1];state.ai=999;tick(.1);if(b.construction.left!==50)return false;w.x=500;w.y=550;tick(1);if(b.construction.left!==49)return false;w.order={kind:'move',x:100,y:100};tick(1);if(b.construction.left!==49)return false;assignBuilder(w,b,false);w.x=500;w.y=550;tick(49);return !b.construction&&b.hp===b.max;})()`));});
test('research takes time and cannot be queued twice for the same upgrade',()=>{const r=game();assert.ok(r(`(()=>{const b=entity('mill',0,500,500,true);state.ai=999;upgrade(b,'lumber');const gold=state.players[0].gold;upgrade(b,'lumber');if(state.players[0].gold!==gold||state.players[0].lumber!==0)return false;tick(30.25);if(state.players[0].lumber!==0)return false;tick(1);return state.players[0].lumber===1&&!b.research;})()`));});
test('units separate from a shared destination instead of stacking',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];const a=entity('worker',0,500,500),b=entity('worker',0,500,500),c=entity('worker',0,500,500);for(let i=0;i<15;i++)separateUnits();return Math.hypot(a.x-b.x,a.y-b.y)>25&&Math.hypot(a.x-c.x,a.y-c.y)>25&&Math.hypot(b.x-c.x,b.y-c.y)>25;})()`));});
test('global work queue includes construction, training and research but excludes gathering',()=>{const r=game();assert.ok(r(`(()=>{const w=state.entities[1];selected=[w];state.resources=[];state.visible.fill(1);build('barracks',500,500);train(state.entities[0],'worker');const mill=entity('mill',0,800,800,true);upgrade(mill,'lumber');w.order={kind:'gather',target:{type:'wood',amount:1000}};const items=workItems();return items.length===3&&items.every(i=>i.total>0&&i.left>0)&&items.some(i=>i.detail==='Waiting for builder');})()`));});
test('shift task queues run waypoints in order and regular orders replace them',()=>{const r=game();assert.ok(r(`(()=>{state.entities=state.entities.filter(e=>e.owner===0);state.resources=[];state.mountains=[];state.ai=999;const w=state.entities[1];w.x=500;w.y=500;selected=[w];issueCommand({x:550,y:500});issueCommand({x:550,y:560},true);for(let i=0;i<20;i++)tick(.05);if(!w.order||w.order.y!==560)return false;for(let i=0;i<25;i++)tick(.05);if(w.order||Math.hypot(w.x-550,w.y-560)>6)return false;queueTask(w,{kind:'move',x:700,y:500});queueTask(w,{kind:'move',x:800,y:500},true);queueTask(w,{kind:'move',x:400,y:500});return !w.tasks.length&&w.order.x===400;})()`));});
test('worker cap includes pending training across multiple strongholds',()=>{const r=game();assert.ok(r(`(()=>{state.players[0].gold=10000;const b=state.entities[0],other=entity('base',0,1000,400,true);for(let i=0;i<11;i++)entity('worker',0,1000+i*30,300);train(b,'worker');train(other,'worker');return workerCount(0)===16&&b.queue.length===1&&other.queue.length===0&&b.queue[0].total===12.5;})()`));});
test('a tree admits only one active collector at the faster lumber rate',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.mountains=[];entity('base',0,100,100,true);entity('base',1,2100,2100,true);const tree={type:'wood',x:500,y:500,amount:1000};state.resources=[tree];state.ai=999;const a=entity('worker',0,480,500),b=entity('worker',0,520,500);a.order=b.order={kind:'gather',target:tree};const before=state.players[0].wood;tick(1);return state.players[0].wood===before&&(a.cargoWood||0)+(b.cargoWood||0)===1.5&&tree.amount===998.5;})()`));});
test('minimap clicks issue orders to selected troops',()=>{const r=game();assert.ok(r(`(()=>{selected=[state.entities[1]];state.resources=[];mini.onmousedown({button:2,clientX:105,clientY:75});return selected[0].order.kind==='move'&&selected[0].order.x===SIZE/2&&selected[0].order.y===SIZE/2;})()`));});
test('fire-arrow research finishes before applying burn, which damages over time and expires',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.mountains=[];entity('base',0,100,100,true);entity('base',1,2100,2100,true);const b=entity('armory',0,300,300,true);state.ai=999;upgrade(b,'fire');tick(42.75);if(state.players[0].fire)return false;tick(1);if(!state.players[0].fire)return false;const archer=entity('ranged',0,500,500),victim=entity('worker',1,600,500);archer.order={kind:'attack',target:victim};fog();tick(.01);if(!victim.burn||!archer.shot.fire)return false;archer.cool=999;const hp=victim.hp;tick(1);if(Math.abs(hp-victim.hp-5)>.001)return false;tick(4);return !victim.burn;})()`));});
test('mountain ranges block ground paths and construction but not flying units',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[];state.mountains=[{x:304,y:352,half:35,height:90}];state.blockCache={};const w=entity('worker',0,230,352),air=entity('air',0,230,352);selected=[w];state.visible.fill(1);if(build('tower',304,352))return false;let hit=false;for(let i=0;i<350;i++){state.time+=.05;move(w,420,352,.05);move(air,420,352,.05);if(Math.abs(w.x-304)<44&&Math.abs(w.y-352)<44)hit=true;}return !hit&&Math.hypot(w.x-420,w.y-352)<6&&Math.hypot(air.x-420,air.y-352)<6;})()`));});
test('each faction starts with 100 of each resource and harvests lumber at 1.5 per second',()=>{const r=game(false);assert.ok(r(`(()=>{if(!state.players.every(p=>p.gold===100&&p.wood===100))return false;state.ai=999;const w=state.entities[1],gold=state.resources.find(r=>r.type==='wood');w.x=gold.x;w.y=gold.y;w.order={kind:'gather',target:gold};tick(1);return state.players[0].wood===100&&w.cargoWood===1.5;})()`));});
test('gathering selection rings are green only during active collection',()=>{const r=game();assert.ok(r(`(()=>{const w=state.entities[1],tree=state.resources.find(r=>r.type==='wood');w.order={kind:'gather',target:tree};w.x=tree.x-20;w.y=tree.y;tree.collectorId=w.id;if(selectionRingColor(w)!=='#57eb87')return false;tree.collectorId=999;if(selectionRingColor(w)==='#57eb87')return false;tree.collectorId=w.id;w.x-=100;return selectionRingColor(w)==='#dce9b3';})()`));});
test('menu allegiance updates to The Dominion and back to Dawnward',()=>{const r=game();assert.ok(r(`(()=>{setFaction('horde');if($('raceBannerName').textContent!=='The Dominion'||$('selectedRaceBanner').dataset.faction!=='horde')return false;setFaction('human');return $('raceBannerName').textContent==='The Dawnward'&&$('raceBannerType').textContent==='Human kingdoms';})()`));});
test('wall construction refuses to overlap a collector without crashing',()=>{const r=game();assert.ok(r(`(()=>{state.resources=[];state.visible.fill(1);const w=state.entities[1];w.x=304;w.y=304;selected=[w];return build('wall',304,304)===false;})()`));});
test('map choices place mountain ranges in different locations and spawns can vary',()=>{const r=game();assert.ok(r(`(()=>{const maps=Object.keys(mapDefinitions).map(key=>JSON.stringify(makeMountains(key)));const a=spawnLocations(()=>.999),b=spawnLocations(()=>0);return new Set(maps).size===3&&JSON.stringify(a[0])!==JSON.stringify(b[0])&&new Set(b.map(p=>p.join(','))).size===6;})()`));});
test('cancelling an in-progress troop refunds its costs and leaves other queued jobs intact',()=>{const r=game();assert.ok(r(`(()=>{state.ai=999;const b=state.entities[0],gold=state.players[0].gold;train(b,'worker');train(b,'worker');tick(2);const id=b.queue[0].id;if(!cancelProduction(b.id,id))return false;return b.queue.length===1&&b.queue[0].left===12.5&&state.players[0].gold===gold-50;})()`));});
test('cancelled research refunds costs and never applies the upgrade',()=>{const r=game();assert.ok(r(`(()=>{state.ai=999;const b=entity('mill',0,500,500,true),before=state.players[0].gold;upgrade(b,'lumber');tick(5);if(!cancelProduction(b.id,'research'))return false;tick(30);return state.players[0].gold===before&&state.players[0].lumber===0&&!b.research;})()`));});
test('Stronghold progresses three times and unlocks tier 2 and tier 3 research',()=>{const r=game();assert.ok(r(`(()=>{state.ai=999;state.players[0].gold=10000;state.players[0].wood=10000;const b=state.entities[0],mill=entity('mill',0,500,500,true);state.players[0].lumber=1;upgrade(mill,'lumber');if(mill.research)return false;upgrade(b,'stronghold');tick(68.75);if(b.level!==2||b.max!==3800)return false;upgrade(mill,'lumber');tick(43.75);if(state.players[0].lumber!==2)return false;upgrade(mill,'lumber');if(mill.research)return false;upgrade(b,'stronghold');tick(81.25);upgrade(mill,'lumber');tick(56.25);if(state.players[0].lumber!==3)return false;upgrade(b,'stronghold');tick(93.75);upgrade(b,'stronghold');return b.level===4&&b.max===4800&&!b.research;})()`));});
test('Harvest Guild capacity increases worker limit only after research finishes',()=>{const r=game();assert.ok(r(`(()=>{state.ai=999;const mill=entity('mill',0,500,500,true);upgrade(mill,'capacity');if(workerLimit(0)!==16)return false;tick(31.25);if(workerLimit(0)!==20)return false;upgrade(mill,'capacity');return !mill.research;})()`));});
test('explicit Move requires right-click and does not gather or attack',()=>{const r=game();assert.ok(r(`(()=>{const w=state.entities[1];selected=[w];commandMode='move';canvas.onpointerdown({button:0,clientX:300,clientY:450});if(w.order||commandMode!=='move')return false;const gold=state.resources.find(r=>r.type==='gold'&&visible(r.x,r.y));canvas.onpointerdown({button:2,clientX:gold.x,clientY:gold.y,preventDefault(){}});return w.order.kind==='move'&&commandMode===null;})()`));});
test('character stats show upgrade-adjusted damage, armor and gathering rate',()=>{const r=game();assert.ok(r(`(()=>{const a=entity('melee',0,500,500);state.players[0].meleeTraining=2;const stats=Object.fromEntries(characterStats(a)),worker=Object.fromEntries(characterStats(state.entities[1]));return stats.Damage==='25.2'&&stats.Armor==='36%'&&stats.Range===25&&stats.Speed===105&&worker['Gather rate']==='1.50/s';})()`));});
test('game clock displays elapsed minutes and seconds and resets on a new match',()=>{const r=game();assert.equal(r('formatGameTime(0)'), '00:00');assert.equal(r('formatGameTime(65.9)'), '01:05');assert.equal(r('formatGameTime(3600)'), '60:00');assert.equal(r('state.time=125;updateUI();$("gameTimer").textContent'),'02:05');assert.equal(r('start();$("gameTimer").textContent'),'00:00');});
test('attack poses have a windup, fast strike and recovery',()=>{const r=game();assert.equal(r('actionPose(0).weapon'),0);assert.equal(r('actionPose(.32).weapon'),-1);assert.equal(r('actionPose(.48).weapon'),1);assert.equal(r('actionPose(1).weapon'),0);assert.ok(r('actionPose(.2).torso<0 && actionPose(.48).torso>0'))});
test('peasants repair only damaged friendly Strongholds and finish at full health',()=>{const r=game();assert.ok(r(`(()=>{state.ai=999;const b=state.entities[0],w=state.entities[1];b.hp=b.max-30;w.x=b.x;w.y=b.y+60;selected=[w];issueCommand({x:b.x,y:b.y});if(w.order.kind!=='repair')return false;const gold=state.players[0].gold;tick(.5);if(b.hp!==b.max-20||w.action.kind!=='repair')return false;tick(1);return b.hp===b.max&&!w.order&&state.players[0].gold===gold;})()`));});
test('repair workers travel before repairing and queued repair resumes the next task',()=>{const r=game();assert.ok(r(`(()=>{state.ai=999;const b=state.entities[0],w=state.entities[1];b.hp=b.max-10;w.x=b.x+200;w.y=b.y;queueTask(w,{kind:'repair',target:b});queueTask(w,{kind:'move',x:900,y:900},true);tick(.1);if(b.hp!==b.max-10)return false;w.x=b.x;w.y=b.y+60;tick(.5);return b.hp===b.max&&w.order.kind==='move'&&w.order.x===900;})()`));});
test('repair mode rejects enemy targets and explicit Move never repairs',()=>{const r=game();assert.ok(r(`(()=>{const b=state.entities[0],w=state.entities[1],enemy=state.entities.find(e=>e.owner===1&&e.type==='base');b.hp-=50;selected=[w];commandMode='repair';issueCommand({x:enemy.x,y:enemy.y});if(w.order||commandMode!=='repair')return false;commandMode='move';issueCommand({x:b.x,y:b.y});if(w.order.kind!=='move')return false;w.order={kind:'repair',target:enemy};repairTick(w,1);return !w.order&&enemy.hp===enemy.max;})()`));});
test('Frontier-inspired Aegis Shield protects nearby troops, expires, and has a cooldown',()=>{const r=game();assert.ok(r(`(()=>{state.ai=999;const hero=entity('hero',0,500,500),near=entity('melee',0,520,500),far=entity('melee',0,900,500),enemy=entity('melee',1,530,500);if(!heroAbility(hero)||shieldMultiplier(near)!==.5||shieldMultiplier(far)!==1||shieldMultiplier(enemy)!==1||heroAbility(hero))return false;state.time+=5;return shieldMultiplier(near)===1&&hero.abilityReady===20;})()`));});
test('Dominion Cleave hits enemies in range without hurting allies or distant enemies',()=>{const r=game();assert.ok(r(`(()=>{state.players[0].faction='horde';const hero=entity('hero',0,500,500),ally=entity('melee',0,520,500),near=entity('melee',1,550,500),far=entity('melee',1,1000,500);if(!heroAbility(hero))return false;return near.hp===near.max-55&&far.hp===far.max&&ally.hp===ally.max&&!heroAbility(hero);})()`));});
test('Stop ends an attack and prevents automatic reacquisition',()=>{const r=game();assert.ok(r(`(()=>{state.ai=999;state.mountains=[];const a=entity('melee',0,500,500),enemy=entity('worker',1,520,500);queueTask(a,{kind:'attack',target:enemy});tick(.01);stopUnit(a);const hp=enemy.hp,x=a.x;for(let i=0;i<20;i++)tick(.05);return enemy.hp===hp&&a.order.kind==='stop'&&!a.action&&Math.abs(a.x-x)<15;})()`));});
test('Move cancels combat while Shift preserves attack before queued movement',()=>{const r=game();assert.ok(r(`(()=>{state.ai=999;state.mountains=[];const a=entity('melee',0,500,500),enemy=entity('worker',1,530,500);queueTask(a,{kind:'attack',target:enemy});queueTask(a,{kind:'move',x:800,y:500},true);if(a.order.kind!=='attack'||a.tasks.length!==1)return false;queueTask(a,{kind:'move',x:400,y:500});const hp=enemy.hp;tick(.5);return a.order.kind==='move'&&a.x<500&&enemy.hp===hp&&!a.tasks.length;})()`));});
test('left-click open ground never issues a move and right-click does',()=>{const r=game();assert.ok(r(`(()=>{const w=state.entities[1];selected=[w];canvas.onpointerdown({button:0,clientX:800,clientY:500});if(w.order)return false;drag=null;canvas.onpointerdown({button:2,clientX:800,clientY:500,preventDefault(){}});return w.order.kind==='move'&&w.order.x===800;})()`));});
test('AI balances gold and lumber, handles a single construction site and obeys difficulty',()=>{const r=game();assert.ok(r(`(()=>{state.resources=state.resources.filter(r=>r.x>1800);state.difficulty='hard';ai();const workers=state.entities.filter(e=>e.owner===1&&e.type==='worker');const gather=workers.filter(w=>w.order?.kind==='gather');return gather.some(w=>w.order.target.type==='wood')&&gather.some(w=>w.order.target.type==='gold')&&state.entities.filter(e=>e.owner===1&&e.construction).length<=1&&difficultyRules.hard.rethink<difficultyRules.easy.rethink&&difficultyRules.hard.raid<difficultyRules.easy.raid;})()`));});
test('AI defends its base and retreats wounded troops without knowing distant opponents',()=>{const r=game();assert.ok(r(`(()=>{const base=state.entities.find(e=>e.owner===1&&e.type==='base');const defender=entity('melee',1,base.x+50,base.y),wounded=entity('melee',1,base.x+60,base.y),raider=entity('melee',0,base.x+100,base.y);wounded.hp=10;state.difficulty='hard';ai();return defender.order.kind==='attack'&&defender.order.target===raider&&wounded.order.kind==='move'&&state.players[1].intel.length===0;})()`));});
test('stopped infantry cannot keep damaging a building and X clears group attack queues',()=>{const r=game();assert.ok(r(`(()=>{state.ai=999;state.mountains=[];const b=entity('barracks',1,600,600,true),a=entity('melee',0,560,600),archer=entity('ranged',0,480,600);selected=[a,archer];for(const unit of selected){queueTask(unit,{kind:'attack',target:b});queueTask(unit,{kind:'move',x:700,y:700},true);}tick(.01);window.onkeydown({key:'x',preventDefault(){}});const hp=b.hp;for(let i=0;i<100;i++)tick(.05);return b.hp===hp&&selected.every(e=>e.order.kind==='stop'&&e.manualPassive&&!e.action&&!e.shot&&!e.tasks.length);})()`));});
test('a new order releases a stopped infantry unit even with Shift held',()=>{const r=game();assert.ok(r(`(()=>{const a=entity('melee',0,500,500);stopUnit(a);queueTask(a,{kind:'move',x:800,y:500},true);return !a.manualPassive&&a.order.kind==='move'&&!a.tasks.length;})()`));});
test('hero aura descriptions include the faction effect and radius',()=>{const r=game();assert.match(r("heroAuraDescription('human')"),/190.*30% less/);assert.match(r("heroAuraDescription('horde')"),/190.*30% more/);});

test('16-frame artwork retains all eight facing directions with valid crop indices',()=>{const c=vm.createContext({Image:class{},Math});vm.runInContext(fs.readFileSync(require.resolve('../frontier-art.js'),'utf8'),c);for(let dir=-8;dir<=8;dir++){const f=vm.runInContext(`frontierFrame({id:1,facing:${dir}*Math.PI/4,action:{duration:1,until:1}},.95)`,c);assert.equal(f.dir,(dir+16)%8);assert.equal(f.phase,2);assert.equal(f.frame,15);}const idle=vm.runInContext('frontierFrame({id:1,facing:0},2)',c);assert.ok(idle.frame>=0&&idle.frame<16);});

test('enemy buildings remain remembered through fog without exposing unseen destruction',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];const scout=entity('worker',0,600,600),enemy=entity('barracks',1,650,600,true),unseen=entity('base',1,1900,1900,true);fog();if(!state.enemyBuildings[enemy.id]||state.enemyBuildings[unseen.id])return false;scout.x=100;scout.y=100;fog();enemy.hp=0;state.entities=state.entities.filter(e=>e.hp>0);fog();if(!state.enemyBuildings[enemy.id])return false;scout.x=650;scout.y=600;fog();return !state.enemyBuildings[enemy.id];})()`));});
test('every formation puts ranged troops behind melee for different movement headings',()=>{const r=game();assert.ok(r(`(()=>{const troops=['sniper','ranged','melee','siege','melee','ranged','air2'].map((type,i)=>entity(type,0,500+i*20,500));for(const kind of Object.keys(formationDefinitions))for(const heading of [0,Math.PI/2,Math.PI,-Math.PI/2]){const slots=formationSlots(troops,{x:1200,y:1200},kind,heading),front=troops.filter(e=>e.type==='melee').map(e=>slots.get(e.id)),rear=troops.filter(e=>['ranged','sniper','siege'].includes(e.type)).map(e=>slots.get(e.id)),project=p=>p.x*Math.cos(heading)+p.y*Math.sin(heading);if(Math.min(...front.map(project))<=Math.max(...rear.map(project)))return false;if(new Set([...slots.values()].map(p=>p.x+':'+p.y)).size!==troops.length)return false;}return true;})()`));});
test('formation movement preserves Shift queues and regular movement cancels combat',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];const a=entity('melee',0,700,700),b=entity('sniper',0,730,700),target=entity('base',1,800,700,true);selected=[b,a];queueTask(a,{kind:'attack',target});queueTask(b,{kind:'attack',target});state.formation='line';commandMode='move';issueCommand({x:1000,y:700},true);if(a.order.kind!=='attack'||b.order.kind!=='attack'||a.tasks.length!==1||b.tasks.length!==1||a.tasks[0].x<=b.tasks[0].x)return false;commandMode='move';issueCommand({x:1000,y:900});return a.order.kind==='move'&&b.order.kind==='move'&&a.tasks.length===0&&b.tasks.length===0;})()`));});
test('second air unit trains at a roost, follows a rally and flies through ground obstacles',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.ai=999;state.mountains=[];entity('base',0,100,100,true).level=3;const roost=entity('roost',0,500,500,true);roost.rally={x:900,y:600};train(roost,'air2');for(let i=0;i<251;i++)tick(.1);const bird=state.entities.find(e=>e.type==='air2');if(!bird||!isFlying(bird)||bird.order.kind!=='move'||units.air2.gold!==280)return false;const wall=entity('wall',1,bird.x+30,bird.y,true);state.wallVersion++;state.blockCache={};const x=bird.x;move(bird,x+100,bird.y,1);return bird.x>x+30&&names.human.air2==='Fire Phoenix'&&names.horde.air2==='Dominion Dragon';})()`));});
test('phoenix and dragon fire attacks apply damage and burning without hurting allies',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.ai=999;const bird=entity('air2',0,800,800),enemy=entity('melee',1,870,800),ally=entity('melee',0,875,800);stopUnit(enemy);stopUnit(ally);queueTask(bird,{kind:'attack',target:enemy});const original=enemy.hp;tick(.1);if(!(enemy.hp<original&&enemy.burn.left>3.8&&bird.shot.fire&&ally.hp===ally.max))return false;stopUnit(bird);const burningHp=enemy.hp;tick(.5);return enemy.hp<burningHp&&ally.hp===ally.max;})()`));});
test('selected group roster lists every unit by type and uses formation controls',()=>{const r=game();assert.ok(r(`(()=>{selected=[entity('melee',0,600,600),entity('melee',0,630,600),entity('sniper',0,650,600)];updateUI();const html=$('groupRoster').innerHTML;if($('groupRoster').hidden||$('formationPane').hidden||!html.includes('Dawn Knight × 2')||!html.includes('Musketeer × 1')||selected.some(e=>!html.includes('#'+e.id)))return false;selected=[selected[0]];updateUI();return $('groupRoster').hidden&&$('formationPane').hidden;})()`));});
test('assembled formations hold their ranks and face forward when movement completes',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.mountains=[];state.resources=[];state.plateaus=[];state.rivers=[];state.ai=999;entity('base',0,100,100,true);entity('base',1,2200,2200,true);selected=['melee','melee','ranged','sniper'].map((type,i)=>entity(type,0,600+i*55,700));chooseFormation('box');for(let i=0;i<250;i++)tick(.1);return selected.every(e=>e.order?.kind==='hold'&&Math.abs(e.facing)<.001)&&Math.min(...selected.filter(e=>e.type==='melee').map(e=>e.x))>Math.max(...selected.filter(e=>e.type!=='melee').map(e=>e.x));})()`));});
test('miners disappear, emerge with cargo and credit gold only at their Stronghold',()=>{const r=game();assert.ok(r(`(()=>{state.ai=999;const w=state.entities[1],mine=state.resources.find(r=>r.type==='gold'),base=state.entities[0],p=state.players[0],before=p.gold;w.x=mine.x;w.y=mine.y;w.order={kind:'gather',target:mine};tick(1);if(!w.hiddenInMine||p.gold!==before)return false;tick(33);if(w.hiddenInMine||w.cargoGold!==10.5||p.gold!==before||w.order.kind!=='deliver')return false;w.x=base.x;w.y=base.y;tick(.1);return p.gold===before+5.90625&&!w.cargoGold&&w.order.kind==='gather';})()`));});
test('Shift mining tasks wait for delivery and Stop releases an underground worker',()=>{const r=game();assert.ok(r(`(()=>{state.ai=999;const w=state.entities[1],mine=state.resources.find(r=>r.type==='gold');w.x=mine.x;w.y=mine.y;queueTask(w,{kind:'gather',target:mine});tick(1);queueTask(w,{kind:'move',x:500,y:500},true);tick(33);w.x=state.entities[0].x;w.y=state.entities[0].y;tick(.1);if(w.order.kind!=='move')return false;w.x=mine.x;w.y=mine.y;queueTask(w,{kind:'gather',target:mine});tick(1);const before=state.players[0].gold;stopUnit(w);return !w.hiddenInMine&&!w.mining&&w.order.kind==='stop'&&state.players[0].gold===before;})()`));});
test('hero talent research is removed without spending resources',()=>{const r=game();assert.ok(r(`(()=>{const b=entity('altar',0,400,400,true),p=state.players[0],gold=p.gold;state.entities[0].level=3;return !researchHero(b,'training')&&!b.research&&p.gold===gold&&heroTree(p.faction,'hero').length===0;})()`));});
test('customized Stop and Move bindings replace defaults',()=>{const r=game();assert.ok(r(`(()=>{selected=[state.entities[1]];keyBindings.stop='Z';keyBindings.move='V';queueTask(selected[0],{kind:'move',x:800,y:800});handleGameKey({key:'z',code:'KeyZ',preventDefault(){}});if(selected[0].order.kind!=='stop')return false;handleGameKey({key:'v',code:'KeyV',preventDefault(){}});return commandMode==='move';})()`));});
test('touch dragging pans the camera without replacing a unit order',()=>{const r=game();assert.ok(r(`(()=>{cam={x:500,y:500};selected=[state.entities[1]];queueTask(selected[0],{kind:'hold'});canvas.onpointerdown({pointerType:'touch',pointerId:1,clientX:100,clientY:100,preventDefault(){}});canvas.onpointermove({pointerType:'touch',pointerId:1,clientX:140,clientY:120,preventDefault(){}});canvas.onpointerup({pointerType:'touch',pointerId:1,clientX:140,clientY:120,preventDefault(){}});return cam.x===460&&cam.y===480&&selected[0].order.kind==='hold'&&!touchGesture;})()`));});
test('touch group gesture selects enclosed units and returns to select mode',()=>{const r=game();assert.ok(r(`(()=>{cam={x:0,y:0};state.entities=[];const a=entity('melee',0,150,150),b=entity('ranged',0,180,180);entity('worker',0,700,700);setTouchMode('group');canvas.onpointerdown({pointerType:'touch',pointerId:1,clientX:100,clientY:100,preventDefault(){}});canvas.onpointermove({pointerType:'touch',pointerId:1,clientX:220,clientY:220,preventDefault(){}});canvas.onpointerup({pointerType:'touch',pointerId:1,clientX:220,clientY:220,preventDefault(){}});return selected.length===2&&selected.includes(a)&&selected.includes(b)&&touchMode==='select';})()`));});
test('mines admit at most five collectors and complete a 10.5-gold load in 4.2 seconds',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[];state.plateaus=[];state.mountains=[];state.ai=999;const mine={type:'gold',x:500,y:500,amount:1000};state.resources=[mine];const workers=Array.from({length:6},()=>entity('worker',0,500,500));for(const w of workers)w.order={kind:'gather',target:mine};tick(.1);if(workers.filter(w=>w.hiddenInMine).length!==5||!workers[5].waitingForMine)return false;tick(4.1);return workers.slice(0,5).every(w=>w.cargoGold===10.5&&!w.hiddenInMine)&&Math.abs(mine.amount-947.5)<1e-6;})()`));});
test('lumber is delivered to the nearest completed friendly outpost before credit',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.plateaus=[];state.mountains=[];state.ai=999;entity('base',0,100,100,true);const outpost=entity('depot',0,500,550,true);entity('depot',1,480,510,true);const tree={type:'wood',x:500,y:500,amount:1000};state.resources=[tree];const w=entity('worker',0,480,500),p=state.players[0],before=p.wood;w.order={kind:'gather',target:tree};tick(34);if(w.cargoWood!==25||p.wood!==before||w.order.kind!=='deliver')return false;w.x=outpost.x;w.y=outpost.y;tick(.1);return p.wood===before+14.0625&&w.cargoWood===0&&w.order.kind==='gather';})()`));});
test('cliff edges require a ramp, plateaus accept buildings and flying units cross freely',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[];state.mountains=[];state.plateaus=[{x:320,y:320,w:192,h:192,height:32,rampX:416}];state.blockCache={};const ground=entity('melee',0,250,380),air=entity('air',0,250,380);if(clearWallLine(ground,416,380)||!flatBuildingSite(416,380,26)||flatBuildingSite(320,380,26))return false;let usedRamp=false;for(let i=0;i<600;i++){state.time+=.05;move(ground,416,380,.05);move(air,416,380,.05);if(onRamp(ground.x,ground.y))usedRamp=true;}return usedRamp&&Math.hypot(ground.x-416,ground.y-380)<7&&Math.hypot(air.x-416,air.y-380)<7;})()`));});
test('tree trunks block ground movement and harvesting an exhausted tree clears the path cache',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.plateaus=[];state.mountains=[];state.ai=999;const tree={type:'wood',x:304,y:352,amount:.5};state.resources=[tree];const w=entity('worker',0,282,352);if(clearWallLine(w,340,352))return false;state.blockCache={old:1};w.order={kind:'gather',target:tree};tick(1);return tree.amount===0&&Object.keys(state.blockCache).length===0&&w.order.kind==='deliver';})()`));});
test('tier three Strongholds fire two independent towers and buildings have increased health',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[];state.plateaus=[];state.mountains=[];state.ai=999;const base=entity('base',0,500,500,true),enemy=entity('melee',1,600,500);state.visible.fill(1);enemy.cool=999;enemy.order={kind:'hold'};defenseAttack(base);if(enemy.hp!==enemy.max)return false;base.level=3;defenseAttack(base);return enemy.hp<enemy.max&&base.defenseShots.length===2&&base.max===3300&&buildings.barracks.hp===1350;})()`));});
test('touching an unfinished friendly building resumes work instead of selecting it',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.plateaus=[];state.mountains=[];cam={x:0,y:0};const w=entity('worker',0,150,150),b=entity('barracks',0,250,250,true);b.construction={left:40,total:40};selected=[w];stopUnit(w);canvas.onpointerdown({pointerType:'touch',pointerId:1,clientX:250,clientY:250,preventDefault(){}});canvas.onpointerup({pointerType:'touch',pointerId:1,clientX:250,clientY:250,preventDefault(){}});return selected[0]===w&&w.order.kind==='build'&&w.order.target===b&&!w.manualPassive;})()`));});
test('administrative code unlocks unlimited spending without affecting AI players',()=>{const r=game(false);assert.ok(r(`(()=>{$('adminCode').value='bad';$('adminUnlock').onclick();if(state.adminResources)return false;$('adminCode').value='RYANISKING';$('adminUnlock').onclick();const aiGold=state.players[1].gold;return state.adminResources&&pay(0,2e9,2e9)&&state.players[1].gold===aiGold;})()`));});
test('flying units gain and lose altitude when crossing high ground',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[];state.mountains=[];state.plateaus=[{x:320,y:320,w:192,h:192,height:64,rampX:416}];state.ai=999;entity('base',0,100,100,true);entity('base',1,2100,2100,true);const air=entity('air',0,400,380);air.order={kind:'stop'};air.flightAltitude=24;for(let i=0;i<20;i++)tick(.1);if(air.flightAltitude<85)return false;air.x=250;for(let i=0;i<20;i++)tick(.1);return air.flightAltitude<27;})()`));});
test('Extreme difficulty has faster decisions, earlier raids and an explicit economy boost',()=>{const r=game(false);assert.ok(r(`(()=>{state.difficulty='extreme';state.entities=state.entities.filter(e=>e.owner===0);const before=state.players[1].gold;ai();return state.players[1].gold===before+10&&difficultyRules.extreme.rethink<difficultyRules.hard.rethink&&difficultyRules.extreme.raid<difficultyRules.hard.raid;})()`));});
test('a worker approaches a blocking tree, loads lumber and delivers it without getting stuck',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.plateaus=[];state.mountains=[];state.ai=999;entity('base',0,300,350,true);entity('base',1,2100,2100,true);const tree={type:'wood',x:500,y:352,amount:100};state.resources=[tree];const w=entity('worker',0,300,352),before=state.players[0].wood;w.order={kind:'gather',target:tree};for(let i=0;i<1000;i++)tick(.05);return state.players[0].wood>=before+14.0625&&tree.amount<=75;})()`));});
test('wood gather reaches chopping range at a normal 60 FPS instead of stopping just outside it',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.plateaus=[];state.mountains=[];state.ai=999;entity('base',0,300,350,true);entity('base',1,2100,2100,true);const tree={type:'wood',x:500,y:352,amount:100};state.resources=[tree];const w=entity('worker',0,300,352),before=state.players[0].wood;w.order={kind:'gather',target:tree};for(let i=0;i<3000;i++)tick(1/60);return state.players[0].wood>=before+14.0625&&tree.amount<=75;})()`));});
test('gather orders recognize tree canopies and mines on raised ground',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[];state.plateaus=[];state.mountains=[];state.visible.fill(1);const w=entity('worker',0,300,350),tree={type:'wood',x:500,y:352,amount:100};state.resources=[tree];selected=[w];issueCommand({x:500,y:307});if(w.order.kind!=='gather'||w.order.target!==tree)return false;state.plateaus=[{x:320,y:320,w:192,h:192,height:32,rampX:416}];tree.x=400;tree.y=380;const p=point({clientX:400,clientY:303});issueCommand(p);return w.order.kind==='gather'&&w.order.target===tree;})()`));});
test('lumber and gold research independently change only their own gathering rates',()=>{const r=game();assert.ok(r(`(()=>{const p=state.players[0],w=state.entities[1],mill=entity('mill',0,500,500,true);p.gold=p.wood=10000;upgrade(mill,'lumber');finishResearch(mill);let stats=Object.fromEntries(characterStats(w));if(p.lumber!==1||p.goldMining!==0||stats['Gather rate']!=='2.10/s'||stats['Gold rate']!=='2.50/s')return false;upgrade(mill,'goldMining');finishResearch(mill);stats=Object.fromEntries(characterStats(w));return p.lumber===1&&p.goldMining===1&&stats['Gather rate']==='2.10/s'&&stats['Gold rate']==='3.50/s';})()`));});
test('each faction permanently chooses one of three heroes and cannot queue a duplicate across Sanctums',()=>{for(const faction of ['human','horde'])for(const type of ['hero','hero2','hero3']){const r=game();assert.ok(r(`(()=>{const p=state.players[0];p.faction='${faction}';state.entities[0].level=3;p.gold=p.wood=10000;const a=entity('altar',0,500,500,true),b=entity('altar',0,700,500,true);train(a,'${type}');for(const t of ['hero','hero2','hero3'])train(b,t);if(a.queue.length!==1||b.queue.length||p.heroChoice!=='${type}')return false;cancelProduction(a.id,String(a.queue[0].id));train(b,['hero','hero2','hero3'].find(t=>t!=='${type}'));if(b.queue.length)return false;train(b,'${type}');return b.queue.length===1;})()`));}});
test('Dominion fire spears burn enemies after research without damaging friendly troops',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[];state.rivers=[];state.plateaus=[];state.mountains=[];state.ai=999;state.players[0].faction='horde';state.visible.fill(1);const armory=entity('armory',0,100,100,true);upgrade(armory,'fire');finishResearch(armory);const troll=entity('ranged',0,500,500),enemy=entity('melee',1,600,500),ally=entity('melee',0,600,510);troll.order={kind:'attack',target:enemy};enemy.order=ally.order={kind:'stop'};tick(.01);if(!enemy.burn||!troll.shot.fire)return false;troll.cool=999;const hp=enemy.hp;tick(1);return Math.abs(hp-enemy.hp-5)<.001&&ally.hp===ally.max;})()`));});
test('new heroes have faction powers and Dragon Sovereign alone is a flying hero',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[];state.rivers=[];state.plateaus=[];state.mountains=[];state.ai=999;state.visible.fill(1);const wizard=entity('hero2',0,500,500),ranger=entity('hero3',0,510,500),witch=entity('hero2',1,530,500),dragon=entity('hero3',1,540,500);if(isFlying(ranger)||!isFlying(dragon)||!heroAbility(wizard)||heroAbility(wizard))return false;if(!heroAbility(witch,true)||!wizard.stunUntil)return false;if(!heroAbility(dragon,true)||!wizard.burn)return false;return heroAuraText(wizard).includes('15%')&&heroAuraText(witch).includes('2 health');})()`));});
test('new hero auras affect allies only within range and expire when the hero dies',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[];state.rivers=[];state.plateaus=[];state.mountains=[];state.ai=999;const troop=entity('melee',0,500,500),ranger=entity('hero3',0,520,500),wizard=entity('hero2',0,520,520),bow=entity('ranged',0,510,500);if(effectiveSpeed(troop)!==units.melee.speed*1.15||battleAuraMultiplier(bow)!==1.15)return false;ranger.x=1000;wizard.hp=0;return effectiveSpeed(troop)===units.melee.speed&&battleAuraMultiplier(bow)===1;})()`));});
test('rivers block direct ground movement, bridges provide routes and flying units cross water',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[];state.plateaus=[];state.mountains=[];state.rivers=[{points:Array.from({length:30},(_,i)=>({x:600,y:100+i*24})),width:44,bridges:[480]}];state.blockCache={};const ground=entity('melee',0,500,300),air=entity('air',0,500,300);if(clearWallLine(ground,700,300)||flatBuildingSite(600,300,28))return false;let bridge=false;for(let i=0;i<500;i++){state.time+=.05;move(ground,700,300,.05);move(air,700,300,.05);if(Math.abs(ground.x-600)<25&&Math.abs(ground.y-480)<58)bridge=true;}return bridge&&Math.hypot(ground.x-700,ground.y-300)<7&&Math.hypot(air.x-700,air.y-300)<7;})()`));});
test('pig code summons a player flying pig at the Stronghold without changing resources',()=>{const r=game(false);assert.ok(r(`(()=>{const before=state.players.map(p=>[p.gold,p.wood]);$('adminCode').value='WHOLETTHEPIGSOUT';$('adminUnlock').onclick();const pig=state.entities.find(e=>e.type==='pig'),base=state.entities.find(e=>e.type==='base'&&e.owner===0);return pig?.owner===0&&isFlying(pig)&&Math.hypot(pig.x-base.x,pig.y-base.y)<150&&!state.adminResources&&state.players.every((p,i)=>p.gold===before[i][0]&&p.wood===before[i][1]);})()`));});
test('pig code entered before a match summons one pig in the next battle for either faction',()=>{const r=game(false);assert.ok(r(`(()=>{state=null;$('adminCode').value='WHOLETTHEPIGSOUT';$('adminUnlock').onclick();for(const race of ['human','horde']){faction=race;start();if(state.entities.filter(e=>e.type==='pig'&&e.owner===0).length!==1)return false;}return true;})()`));});
test('pig flies across obstacles, leaves bounded fading trails and can stop laser attacks',()=>{const r=game();assert.ok(r(`(()=>{state.ai=999;state.entities=[];state.visible.fill(1);state.mountains=[];state.resources=[];state.plateaus=[];state.rivers=[];entity('base',0,100,100,true);entity('base',1,2100,2100,true);const pig=entity('pig',0,500,500),target=entity('base',1,650,500,true);queueTask(pig,{kind:'attack',target});tick(.05);if(!pig.shot||target.hp>=target.max||pig.shot.fromHeight<=24)return false;stopUnit(pig);const hp=target.hp;tick(.1);if(pig.shot||target.hp!==hp)return false;entity('wall',1,550,500,true);queueTask(pig,{kind:'move',x:900,y:500});for(let i=0;i<100;i++)tick(.05);if(pig.x<890||pig.rainbow.length>48)return false;stopUnit(pig);for(let i=0;i<35;i++)tick(.05);return pig.rainbow.length===0;})()`));});
test('three research ranks queue in order, reject a fourth, and complete sequentially',()=>{const r=game();assert.ok(r(`(()=>{state.ai=999;const p=state.players[0];p.gold=p.wood=10000;state.entities[0].level=3;const b=entity('mill',0,350,300,true);upgrade(b,'lumber');upgrade(b,'lumber');upgrade(b,'lumber');const gold=p.gold;upgrade(b,'capacity');if(researchJobs(b).length!==3||p.gold!==gold||b.research.level!==1)return false;tick(b.research.left+.01);if(p.lumber!==1||b.research.level!==2)return false;tick(b.research.left+.01);tick(b.research.left+.01);return p.lumber===3&&!b.research&&researchJobs(b).length===0;})()`));});
test('canceling a prerequisite research rank refunds dependent queued ranks',()=>{const r=game();assert.ok(r(`(()=>{const p=state.players[0];p.gold=p.wood=10000;state.entities[0].level=3;const b=entity('mill',0,350,300,true);upgrade(b,'lumber');upgrade(b,'lumber');upgrade(b,'lumber');return cancelProduction(b.id,'research:'+b.research.id)&&researchJobs(b).length===0&&p.gold===10000&&p.wood===10000&&p.lumber===0;})()`));});
test('different queued upgrades preserve their order when a waiting job is canceled',()=>{const r=game();assert.ok(r(`(()=>{const p=state.players[0];p.gold=p.wood=10000;const b=entity('mill',0,350,300,true);upgrade(b,'lumber');upgrade(b,'goldMining');upgrade(b,'capacity');const removed=b.researchQueue[0];if(!cancelProduction(b.id,'research:'+removed.id))return false;finishResearch(b);return p.lumber===1&&b.research.key==='capacity'&&researchJobs(b).length===1;})()`));});
test('removed hero talents cannot create research queue jobs',()=>{const r=game();assert.ok(r(`(()=>{const b=entity('altar',0,400,400,true);researchHero(b,'training');researchHero(b,'vitality');return researchJobs(b).length===0;})()`));});
test('tutorial selection and movement advance real lessons and normal starts reset practice',()=>{const r=game(true,true);assert.ok(r(`(()=>{startTutorial();state.count=0;if(!tutorial.active||state.networkMatch||!state.tutorial||state.adminResources)return false;selected=[state.entities.find(e=>e.owner===0&&e.type==='worker')];tutorialAdvance();if(tutorial.step!==1)return false;queueTask(selected[0],{kind:'move',x:selected[0].x+60,y:selected[0].y});tutorialAdvance();if(tutorial.step!==2)return false;start();return !tutorial.active&&!state.tutorial&&state.players[0].gold===100;})()`));});
test('tutorial waits for delivery and does not grant resources or accelerate normal play',()=>{const r=game(true,true);assert.ok(r(`(()=>{startTutorial();tutorial.step=2;const w=state.entities.find(e=>e.owner===0&&e.type==='worker'),base=state.entities[0];w.cargoWood=25;w.x=base.x+200;w.y=base.y;w.order={kind:'deliver'};deliverGold(w,.01);tutorialAdvance();if(tutorial.step!==2)return false;w.x=base.x;deliverGold(w,.01);tutorialAdvance();if(tutorial.step!==3)return false;state.players[0].gold=100;tick(.01);return state.players[0].gold===100;})()`));});
test('tutorial is playable through every lesson using real delivery, construction, research and combat',()=>{const r=game(true,true);assert.equal(r(`(()=>{startTutorial();state.count=0;const stepUntil=n=>{for(let i=0;i<2500&&tutorial.step<n;i++){tick(.1);tutorialAdvance();}if(tutorial.step!==n)throw Error('Stuck at lesson '+tutorial.step+' instead of '+n);};const w=state.entities.find(e=>e.owner===0&&e.type==='worker'),base=state.entities[0];selected=[w];tutorialAdvance();queueTask(w,{kind:'move',x:w.x+20,y:w.y});tutorialAdvance();for(const [type,next]of [['wood',3],['gold',4]]){const resource=state.resources.filter(r=>r.type===type&&terrainHeight(r.x,r.y)===terrainHeight(base.x,base.y)).sort((a,b)=>Math.hypot(a.x-base.x,a.y-base.y)-Math.hypot(b.x-base.x,b.y-base.y))[0];queueTask(w,{kind:'gather',target:resource});stepUntil(next);}train(base,'worker');stepUntil(5);selected=[w];const site=tutorialSite('barracks');if(!site||!build('barracks',site.x,site.y))throw Error('No practice construction site');stepUntil(6);const lodge=state.entities.find(e=>e.owner===0&&e.type==='barracks');train(lodge,'melee');stepUntil(7);const guild=state.entities.find(e=>e.owner===0&&e.type==='mill');upgrade(guild,'lumber');stepUntil(8);const melee=state.entities.find(e=>e.owner===0&&e.type==='melee'),target=state.entities.find(e=>e.id===tutorial.target);queueTask(melee,{kind:'attack',target});stepUntil(9);stopUnit(melee);tutorialAdvance();return tutorial.step;})()`),10);});
test('routes check obstacle clearance along edges and reach destinations behind off-center trees',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[{type:'wood',x:331,y:309,amount:100}];state.mountains=[];state.plateaus=[];state.rivers=[];state.blockCache={};const u=entity('melee',0,260,300);queueTask(u,{kind:'move',x:430,y:300});for(let i=0;i<300;i++){state.time+=.05;move(u,430,300,.05);}return Math.hypot(u.x-430,u.y-300)<6&&!blockedGroundPoint(u.x,u.y,u.size);})()`));});
test('ground units route around buildings while flyers cross them',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[];state.mountains=[];state.plateaus=[];state.rivers=[];state.blockCache={};entity('base',1,400,350,true);const u=entity('melee',0,290,350),air=entity('air',0,290,350);queueTask(u,{kind:'move',x:520,y:350});for(let i=0;i<300;i++){state.time+=.05;move(u,520,350,.05);if(blockedGroundPoint(u.x,u.y,u.size))return false;}move(air,520,350,2);return Math.hypot(u.x-520,u.y-350)<6&&air.x===520;})()`));});
test('unreachable move destinations resolve at reachable ground without endless walking',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[];state.mountains=[{x:500,y:500,half:110}];state.plateaus=[];state.rivers=[];state.blockCache={};const u=entity('melee',0,300,500);queueTask(u,{kind:'move',x:500,y:500});let arrived=false;for(let i=0;i<500;i++){state.time+=.05;if(move(u,500,500,.05)<6){arrived=true;break;}}return arrived&&!blockedGroundPoint(u.x,u.y,u.size)&&Math.hypot(u.x-500,u.y-500)<145&&Math.hypot(u.x-300,u.y-500)>50;})()`));});
test('movement orders outside the map finish at the map edge rather than walking forever',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[];state.mountains=[];state.plateaus=[];state.rivers=[];const u=entity('melee',0,SIZE-100,500);queueTask(u,{kind:'move',x:SIZE+300,y:500});let done=false;for(let i=0;i<100;i++)if(move(u,SIZE+300,500,.05)<6){done=true;break;}return done&&u.x<=SIZE-10&&u.x>SIZE-20;})()`));});
test('maps have thirteen mines, one by every spawn, clustered trees and clear ramps and riverbanks',()=>{const r=game();for(const map of ['highlands','frontier','canyon'])assert.ok(r(`(()=>{mapChoice='${map}';start();const mines=state.resources.filter(r=>r.type==='gold'),trees=state.resources.filter(r=>r.type==='wood');return mines.length===13&&state.spawns.every(([x,y])=>mines.some(m=>Math.hypot(x-m.x,y-m.y)<180))&&trees.length>=220&&trees.filter(t=>trees.some(n=>n!==t&&Math.hypot(n.x-t.x,n.y-t.y)<60)).length/trees.length>.95&&state.resources.every(t=>!onRamp(t.x,t.y)&&!riverAt(t.x,t.y,28));})()`));});
test('infantry research affects only its unit type and keeps tier and three-slot queue restrictions',()=>{const r=game();assert.ok(r(`(()=>{const p=state.players[0];p.gold=p.wood=10000;const armory=entity('armory',0,500,500,true);upgrade(armory,'meleeTraining');upgrade(armory,'rangedTraining');upgrade(armory,'sniperTraining');if(researchJobs(armory).length!==3)return false;upgrade(armory,'fire');if(researchJobs(armory).length!==3)return false;finishResearch(armory);const a=entity('melee',0,600,600),b=entity('ranged',0,620,600),c=entity('sniper',0,640,600);if(Object.fromEntries(characterStats(a)).Damage!=='21.6'||Object.fromEntries(characterStats(b)).Damage!=='15.0'||Object.fromEntries(characterStats(c)).Damage!=='38.0'||armorMultiplier(b)!==1||armorMultiplier(c)!==1)return false;finishResearch(armory);finishResearch(armory);upgrade(armory,'sniperTraining');if(armory.research)return false;state.entities[0].level=2;upgrade(armory,'sniperTraining');return armory.research?.level===2&&p.meleeTraining===1&&p.rangedTraining===1&&p.sniperTraining===1;})()`));});
test('a failed hero purchase does not lock the match choice',()=>{const r=game(false);assert.ok(r(`(()=>{const b=entity('altar',0,500,500,true);train(b,'hero2');return !state.players[0].heroChoice&&!b.queue.length;})()`));});
test('hero talents and their powers cannot be purchased or cast',()=>{const r=game();assert.ok(r(`(()=>{const h=entity('hero2',0,500,500);gainHeroXP(h,100);return h.level===2&&h.skillPoints===0&&!spendHeroPoint(h,'training')&&!castHeroPower(h,'whirlaxe')&&heroRank(h,'training')===0;})()`));});
test('nearby allied kills grant hero XP once, remote kills and friendly deaths do not',()=>{const r=game();assert.ok(r(`(()=>{state.ai=999;const p=state.players[0];p.heroChoice='hero';const h=entity('hero',0,500,500),near=entity('melee',1,520,500),far=entity('melee',1,1800,1800),friendly=entity('worker',0,520,500);for(const e of [near,far,friendly]){e.hp=0;e.lastDamageOwner=0;}resolveCombatDeaths();resolveCombatDeaths();if(h.xp!==45)return false;gainHeroXP(h,555);return h.level===4&&h.xp===0&&h.skillPoints===0;})()`));});
test('hero death loses one level and retraining retains the chosen hero without talents',()=>{const r=game();assert.ok(r(`(()=>{state.ai=999;const p=state.players[0];p.gold=p.wood=10000;const b=entity('altar',0,500,500,true);train(b,'hero3');tick(25.125);const h=state.entities.find(e=>e.type==='hero3'&&e.owner===0);gainHeroXP(h,300);h.hp=0;tick(.01);if(p.heroProgress.level!==2||p.heroProgress.xp!==0)return false;train(b,'hero2');if(b.queue.length)return false;train(b,'hero3');tick(25.125);const revived=state.entities.find(e=>e.type==='hero3'&&e.owner===0);return revived.level===2&&revived.skillPoints===0&&Object.keys(revived.heroSkills).length===0&&revived.hp===revived.max;})()`));});
test('level-one hero death never drops below level one',()=>{const r=game();assert.ok(r(`(()=>{state.players[0].heroChoice='hero';const h=entity('hero',0,500,500);h.hp=0;resolveCombatDeaths();return state.players[0].heroProgress.level===1&&state.players[0].heroProgress.skillPoints===0;})()`));});
test('all six hero classes retain levels without talent trees',()=>{for(const faction of ['human','horde'])for(const type of ['hero','hero2','hero3']){const r=game();assert.ok(r(`(()=>{const p=state.players[0];p.faction='${faction}';p.heroChoice='${type}';const h=entity('${type}',0,500,500);gainHeroXP(h,100);return h.level===2&&heroTree(p.faction,h.type).length===0&&h.skillPoints===0;})()`));}});
