test('left-click switches to a nearby worker even during a pending command',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[];state.plateaus=[];cam={x:0,y:0};const a=entity('worker',0,200,200),b=entity('worker',0,235,200);selected=[a];commandMode='command';canvas.onpointerdown({button:0,clientX:235,clientY:180});canvas.onpointerup({button:0,clientX:235,clientY:180});return selected.length===1&&selected[0]===b&&!commandMode&&!a.order;})()`));});
test('touch selects a worker ahead of overlapping resource hit areas and exits order mode',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.plateaus=[];cam={x:0,y:0};const a=entity('worker',0,200,200),b=entity('worker',0,260,200);state.resources=[{type:'wood',x:265,y:230,amount:500}];state.visible.fill(1);selected=[a];setTouchMode('order');canvas.onpointerdown({pointerType:'touch',pointerId:1,clientX:260,clientY:180,preventDefault(){}});canvas.onpointerup({pointerType:'touch',pointerId:1,clientX:260,clientY:180,preventDefault(){}});return selected.length===1&&selected[0]===b&&touchMode==='select'&&!a.order;})()`));});
test('group gather orders reserve separate accessible trees before workers arrive and all workers can harvest',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[];state.plateaus=[];state.mountains=[];state.rivers=[];state.ai=999;entity('base',0,200,200,true);entity('base',1,2200,2200,true);selected=Array.from({length:4},(_,i)=>entity('worker',0,260+i*34,600));for(let i=0;i<8;i++)state.resources.push({type:'wood',x:500+i*40,y:600,amount:500});state.visible.fill(1);issueCommand({x:500,y:580});if(new Set(selected.map(w=>w.order?.target)).size!==4||selected.some(w=>w.order?.kind!=='gather'||!resourceApproach(w,w.order.target)))return false;for(let i=0;i<300;i++)tick(.05);return selected.every(w=>w.cargoWood>0)&&selected.every((w,i)=>selected.every((v,j)=>i===j||Math.hypot(w.x-v.x,w.y-v.y)>25));})()`));});
test('new and shift-queued gather orders do not reserve another worker\'s tree',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[];state.mountains=[];state.plateaus=[];state.rivers=[];state.visible.fill(1);const a=entity('worker',0,200,300),b=entity('worker',0,230,300);for(let i=0;i<4;i++)state.resources.push({type:'wood',x:400+i*40,y:300,amount:100});const tree=state.resources[0];queueTask(a,{kind:'gather',target:tree});queueTask(b,{kind:'move',x:250,y:300});queueTask(b,{kind:'gather',target:tree},true);return b.tasks.length===1&&b.tasks[0].target!==tree&&treeReserved(tree,b)&&!treeAvailable(tree,b);})()`));});
test('match statistics track deliveries, cumulative worker idle time and completed production without refunds',()=>{const r=game();assert.ok(r(`(()=>{state.ai=999;tick(2);const p=state.players[0],s=p.stats,w=state.entities.find(e=>e.owner===0&&e.type==='worker'),base=state.entities[0];if(s.workerIdle!==8||s.goldGained||s.woodGained||s.fightersBuilt||s.buildingsMade)return false;w.x=base.x;w.y=base.y+base.size;w.cargoGold=7;w.cargoWood=11;w.order={kind:'deliver'};deliverGold(w,.1);const b=entity('barracks',0,500,500,true);train(b,'melee');cancelProduction(b.id,String(b.queue[0].id));if(s.goldGained!==3.9375||s.woodGained!==6.1875||s.fightersBuilt)return false;train(b,'melee');tick(7.6);return s.fightersBuilt===1&&s.goldGained===3.9375&&s.woodGained===6.1875;})()`));});
test('construction and credited destruction count once and match results escape player names',()=>{const r=game();assert.ok(r(`(()=>{const w=state.entities[1],b=entity('tower',0,500,500,true);w.x=500;w.y=550;w.order={kind:'build',target:b};b.construction={left:1,total:1};constructionTick(b,1);constructionTick(b,1);const enemy=entity('tower',1,700,700,true);enemy.hp=0;enemy.lastDamageOwner=0;resolveCombatDeaths();resolveCombatDeaths();state.players[1].name='<img src=x onerror=alert(1)>';showMatchResults('VICTORY');return state.players[0].stats.buildingsMade===1&&state.players[0].stats.buildingsDestroyed===1&&$('end').innerHTML.includes('&lt;img')&&!$('end').innerHTML.includes('<img');})()`));});
test('collectors wait outside an occupied tree instead of piling onto its approach',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[];state.mountains=[];state.rivers=[];state.plateaus=[];state.ai=999;entity('base',0,100,100,true);entity('base',1,2100,2100,true);const tree={type:'wood',x:500,y:500,amount:1000};state.resources=[tree];const a=entity('worker',0,480,500),b=entity('worker',0,200,500);a.order={kind:'gather',target:tree};b.order={kind:'gather',target:tree};tree.collectorId=a.id;tick(1);if(b.x!==200||a.cargoWood!==1.5)return false;stopUnit(a);tick(1);return b.x>200&&b.order.target===tree;})()`));});
test('six single-player banners start on a larger map with independent armies and private fog',()=>{const r=game(false);assert.ok(r(`(()=>{const colors=['#ef685a','#b88af0','#f2c45b','#81d186','#f19cd1'];for(let i=1;i<=5;i++){$('ai'+i).value=i%2?'horde':'human';$('c'+i).value=colors[i-1];}start();return SIZE===4000&&N===100&&!state.networkMatch&&state.players.length===6&&state.spawns.length===6&&new Set(state.spawns.map(s=>s.join(','))).size===6&&state.entities.filter(e=>e.type==='base').length===6&&state.players.every((p,i)=>state.entities.filter(e=>e.owner===i&&e.type==='worker').length===4)&&state.seen.length===10000&&state.players.slice(1).every(p=>p.ai)&&state.resources.filter(r=>r.type==='gold').length===13;})()`));});
test('RYANISKING completes current and new construction, counts buildings once and releases builders',()=>{const r=game(false);assert.ok(r(`(()=>{state.resources=[];state.mountains=[];state.plateaus=[];state.rivers=[];state.visible.fill(1);state.players[0].gold=state.players[0].wood=10000;const w=state.entities[1];selected=[w];build('barracks',500,500);const b=state.entities.find(e=>e.type==='barracks');if(!b.construction)return false;$('adminCode').value='RYANISKING';$('adminUnlock').onclick();if(b.construction||b.hp!==b.max||w.order?.kind==='build'||state.players[0].stats.buildingsMade!==1)return false;build('wall',600,600);const wall=state.entities.find(e=>e.type==='wall');return !wall.construction&&wall.hp===wall.max&&state.players[0].stats.buildingsMade===2&&state.wallVersion>0&&state.players[1].gold===100;})()`));});
test('Hard AI scouts early, prefers exposed resource buildings and does not receive an economy cheat',()=>{const r=game(false);assert.ok(r(`(()=>{state.difficulty='hard';state.resources=[];const p=state.players[1],base=state.entities.find(e=>e.owner===1&&e.type==='base');const scout=entity('ranged',1,base.x-100,base.y);state.time=21;p.gold=p.wood=0;const gold=p.gold;ai();if(scout.order?.kind!=='move'||p.gold!==gold)return false;const stronghold=state.entities.find(e=>e.owner===0&&e.type==='base'),depot=entity('depot',0,800,800,true);p.intel=[stronghold,depot];for(let i=0;i<5;i++)entity('melee',1,base.x-120-i*35,base.y);state.time=41;ai();return scout.order?.kind==='attackMove'&&Math.hypot(scout.order.x-depot.x,scout.order.y-depot.y)<250&&difficultyRules.hard.rethink<1&&difficultyRules.hard.raid<=40&&difficultyRules.hard.workers===24;})()`));});

test('ground troops go around close trees instead of squeezing through their gap; flyers cross freely',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[{type:'wood',x:336,y:317,amount:100},{type:'wood',x:336,y:355,amount:100}];state.mountains=[];state.plateaus=[];state.rivers=[];state.blockCache={};state.wallVersion++;const u=entity('worker',0,240,336),air=entity('air',0,240,336);if(clearWallLine(u,440,336))return false;let routed=false;for(let i=0;i<300;i++){state.time+=.05;move(u,440,336,.05);move(air,440,336,.05);if(blockedGroundPoint(u.x,u.y,u.size))return false;if(Math.abs(u.y-336)>40)routed=true;}return routed&&Math.hypot(u.x-440,u.y-336)<6&&Math.hypot(air.x-440,air.y-336)<6;})()`));});
test('forest edge workers can harvest with wider tree clearance and depleted trees reopen the path',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[{type:'wood',x:336,y:317,amount:100},{type:'wood',x:336,y:355,amount:100}];state.mountains=[];state.plateaus=[];state.rivers=[];state.blockCache={};state.wallVersion++;const u=entity('worker',0,240,336);if(!resourceApproach(u,state.resources[0])||clearWallLine(u,440,336))return false;state.resources.forEach(t=>t.amount=0);state.wallVersion++;return clearWallLine(u,440,336)&&wallRoute(u,440,336).length>0;})()`));});
test('nearby collision lookup matches exhaustive obstacle checks across boundaries and long paths',()=>{const r=game();assert.ok(r(`(()=>{const exhaustive=eval('('+clearWallLine.toString().replace('nearbyObstacles(obstacles,e,x,y)','obstacles')+')');const obstacles=groundObstacles();for(let i=0;i<700;i++){const e={x:10+(i*157)%3100,y:10+(i*73)%3100,size:[9,14,22][i%3]},x=e.x+(i%2?31:400),y=e.y+(i%3?-47:280);if(clearWallLine(e,x,y,obstacles)!==exhaustive(e,x,y,obstacles))return false;}return true;})()`));});
test('a valid forest detour is reused after two seconds rather than searched repeatedly',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[{type:'wood',x:336,y:317,amount:100},{type:'wood',x:336,y:355,amount:100}];state.mountains=[];state.plateaus=[];state.rivers=[];state.blockCache={};state.wallVersion++;const u=entity('worker',0,240,336);queueTask(u,{kind:'move',x:440,y:336});move(u,440,336,0);const route=u.route;if(!route?.points.length)return false;state.time+=3;move(u,440,336,0);if(u.route!==route)return false;state.wallVersion++;move(u,440,336,0);return u.route!==route;})()`));});
test('all six starting areas on every map stay off rivers and have room for bases and workers',()=>{const r=game();for(const key of ['highlands','frontier','canyon'])assert.ok(r(`(()=>{mapChoice='${key}';const colors=['#53c9eb','#ef685a','#b88af0','#f2c45b','#81d186','#f19cd1'];start({players:colors.map((color,i)=>({name:'Player '+i,color,faction:i%2?'horde':'human',ai:i>0}))});const obstacles=[...cliffObstacles(),...state.mountains];return state.spawns.length===6&&state.spawns.every(([x,y])=>safeSpawnSite(x,y,obstacles)&&!riverAt(x,y,220))&&state.entities.every(e=>terrainHeight(e.x,e.y)===0&&(e.building?flatBuildingSite(e.x,e.y,e.size):!blockedGroundPoint(e.x,e.y,e.size)))&&state.spawns.every(([x,y])=>state.resources.some(r=>r.type==='gold'&&Math.hypot(r.x-x,r.y-y)<180));})()`),key);});
test('central river start anchors are relocated consistently in previews and shuffled matches',()=>{const r=game();for(const key of ['highlands','frontier','canyon'])assert.ok(r(`(()=>{mapChoice='${key}';start();const preview=spawnLocations(()=>.999),shuffled=spawnLocations(()=>0);return preview[4][0]!==SIZE/2&&preview[5][0]!==SIZE/2&&preview.map(p=>p.join(',')).sort().join('|')===shuffled.map(p=>p.join(',')).sort().join('|');})()`),key);});
test('siege buildings and artillery require Stronghold 2; roost and both flyers require Stronghold 3',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[];state.mountains=[];state.plateaus=[];state.rivers=[];state.visible.fill(1);const base=entity('base',0,200,200,true),w=entity('worker',0,260,200);selected=[w];state.players[0].gold=10000;state.players[0].wood=10000;const forge=entity('forge',0,500,500,true),roost=entity('roost',0,700,500,true),before=state.players[0].gold;for(const t of ['forge','foundry','bastion','roost'])if(build(t,900,900))return false;train(forge,'siege');train(roost,'air');train(roost,'air2');if(forge.queue.length||roost.queue.length||state.players[0].gold!==before)return false;base.level=2;if(!build('forge',1000,1000)||!build('foundry',1200,1000)||build('roost',1400,1000))return false;train(forge,'siege');train(roost,'air');if(forge.queue.length!==1||roost.queue.length)return false;base.level=3;if(!build('roost',1400,1000))return false;train(roost,'air');train(roost,'air2');return roost.queue.length===2;})()`));});
test('peons deliver both resources from a diagonal approach outside a stronghold corner',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[];state.mountains=[];state.plateaus=[];state.rivers=[];state.ai=999;state.players[0].faction='horde';entity('base',0,400,400,true);entity('base',1,2400,2400,true);const w=entity('worker',0,480,480);w.cargoGold=10.5;w.cargoWood=25;w.order={kind:'deliver'};const p=state.players[0],gold=p.gold,wood=p.wood;for(let i=0;i<300&&w.order?.kind==='deliver';i++)tick(.05);return !w.cargoGold&&!w.cargoWood&&p.gold===gold+5.90625&&p.wood===wood+14.0625;})()`));});
test('delivery chooses an accessible outpost when the nearest one is surrounded by walls',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[];state.mountains=[];state.plateaus=[];state.rivers=[];state.ai=999;entity('base',0,180,400,true);entity('base',1,2400,2400,true);entity('depot',0,496,400,true);for(let y=304;y<=496;y+=32)for(let x=400;x<=592;x+=32)if(x===400||x===592||y===304||y===496)entity('wall',0,x,y,true);state.wallVersion++;const w=entity('worker',0,650,400);w.cargoWood=25;w.order={kind:'deliver'};const before=state.players[0].wood;for(let i=0;i<600&&w.order?.kind==='deliver';i++)tick(.05);return !w.cargoWood&&state.players[0].wood===before+14.0625;})()`));});
test('The Devoured is additional Dominion-only melee infantry with its own armor research and formations',()=>{const r=game();assert.ok(r(`(()=>{state.ai=999;const p=state.players[0],base=state.entities[0],b=entity('barracks',0,500,500,true);p.gold=p.wood=10000;train(b,'devoured');if(b.queue.length)return false;p.faction='horde';train(b,'devoured');if(b.queue.length)return false;base.level=3;train(b,'devoured');if(b.queue.length!==1||b.queue[0].gold!==130||b.queue[0].wood!==70)return false;tick(15.125);const u=state.entities.find(e=>e.type==='devoured');if(!u||u.hp!==320||isFlying(u)||formationRole(u)!==0||armorMultiplier(u)!==.65)return false;const armory=entity('armory',0,700,500,true);upgrade(armory,'devouredTraining');if(armory.research?.key!=='devouredTraining')return false;tick(50.0);return infantryRank(u)===1&&Math.abs(armorMultiplier(u)-.57)<.00001&&names.horde.devoured==='The Devoured';})()`));});
test('every point in starting clearings stays away from bent rivers on all maps',()=>{const r=game();for(const map of ['highlands','frontier','canyon'])assert.ok(r(`(()=>{mapChoice='${map}';start();for(const [x,y] of state.spawns)for(let dx=-160;dx<=160;dx+=20)for(let dy=-160;dy<=160;dy+=20)if(riverAt(x+dx,y+dy,20))return false;return true;})()`),map);});
test('trained ground troops use a river-free reachable exit and wait if the building is enclosed',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[];state.mountains=[];state.plateaus=[];state.rivers=[{points:[{x:565,y:0},{x:565,y:SIZE}],width:44,bridges:[]}];state.ai=999;const base=entity('base',0,460,500,true);entity('base',1,2400,2400,true);train(base,'worker');tick(12.625);const w=state.entities.find(e=>e.type==='worker');if(!w||riverAt(w.x,w.y,w.size+8)||blockedGroundPoint(w.x,w.y,w.size))return false;state.rivers=[];for(let y=436;y<=564;y+=32)for(let x=396;x<=524;x+=32)if(x===396||x===524||y===436||y===564)entity('wall',0,x,y,true);state.wallVersion++;return productionSpawnPoint(base,'worker')===null;})()`));});
test('cancelling the main-menu warning preserves match state and confirming exits',()=>{const r=game();assert.ok(r(`(()=>{const match=state;let message='';window.confirm=text=>{message=text;return false;};if($('exit').onclick()!==false||state!==match||!message.includes('Progress will be lost'))return false;window.confirm=()=>true;return $('exit').onclick()===true&&state===null&&$('game').hidden&&$('menu').hidden===false;})()`));});
test('spatial separation works across bucket boundaries and keeps flyers apart from ground collisions',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[];state.mountains=[];state.plateaus=[];state.rivers=[];const a=entity('devoured',0,95,95),b=entity('worker',0,97,96),air=entity('air',0,95,95);for(let i=0;i<20;i++)separateUnits();return Math.hypot(a.x-b.x,a.y-b.y)>30&&air.x===95&&air.y===95;})()`));});
test('minimap terrain classification is reused but rebuilt for a new map',()=>{const r=game();assert.ok(r(`(()=>{const first=minimapTerrainTypes();if(minimapTerrainTypes()!==first)return false;mapChoice='canyon';start();return minimapTerrainTypes()!==first&&minimapTerrainTypes().length===N*N;})()`));});
test('Royal Cavalier matches every Devoured stat, trains only for Dawnward, and has equal independent upgrades',()=>{const r=game();assert.ok(r(`(()=>{if(JSON.stringify(units.cavalier)!==JSON.stringify(units.devoured))return false;state.entities=[];state.resources=[];state.mountains=[];state.plateaus=[];state.rivers=[];state.ai=999;const p=state.players[0],enemy=state.players[1];p.faction='human';enemy.faction='horde';p.gold=p.wood=enemy.gold=enemy.wood=10000;entity('base',0,150,150,true).level=3;entity('base',1,2500,2500,true).level=3;const human=entity('barracks',0,500,500,true),orc=entity('barracks',1,2000,2000,true);train(orc,'cavalier');train(human,'devoured');if(human.queue.length||orc.queue.length)return false;train(human,'cavalier');train(orc,'devoured');if(human.queue[0].gold!==orc.queue[0].gold||human.queue[0].wood!==orc.queue[0].wood||human.queue[0].total!==orc.queue[0].total)return false;tick(15.125);const knight=state.entities.find(e=>e.type==='cavalier'),devoured=state.entities.find(e=>e.type==='devoured');if(!knight||!devoured||knight.size!==devoured.size||armorMultiplier(knight)!==armorMultiplier(devoured)||isFlying(knight)||formationRole(knight)!==0)return false;const a=entity('armory',0,700,500,true),b=entity('armory',1,2200,2000,true);upgrade(a,'cavalierTraining');upgrade(b,'devouredTraining');if(!a.research||!b.research||a.research.gold!==b.research.gold||a.research.wood!==b.research.wood||a.research.total!==b.research.total)return false;tick(50.0);return infantryRank(knight)===1&&infantryRank(devoured)===1&&armorMultiplier(knight)===armorMultiplier(devoured)&&p.devouredTraining===0&&enemy.cavalierTraining===0;})()`));});
test('right-clicking a damaged Stronghold returns distant mixed cargo exactly once',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[];state.mountains=[];state.plateaus=[];state.rivers=[];state.blockCache={};state.ai=999;const b=entity('base',0,300,300,true);entity('base',1,2600,2600,true);const w=entity('worker',0,1100,500);w.cargoGold=10.5;w.cargoWood=25;b.hp-=100;const p=state.players[0],gold=p.gold,wood=p.wood;selected=[w];issueCommand(b);if(w.order.kind!=='deliver'||w.order.target!==b)return false;for(let i=0;i<1000&&(w.cargoGold||w.cargoWood);i++)tick(.05);tick(.1);return w.cargoGold===0&&w.cargoWood===0&&p.gold===gold+5.90625&&p.wood===wood+14.0625&&b.hp===b.max-100;})()`));});
test('Shift return orders preserve the previous move and execute delivery next',()=>{const r=game();assert.ok(r(`(()=>{const w=state.entities[1],b=state.entities[0];w.cargoWood=25;queueTask(w,{kind:'move',x:500,y:450});selected=[w];issueCommand(b,true);return w.order.kind==='move'&&w.tasks.length===1&&w.tasks[0].kind==='deliver'&&w.tasks[0].target===b;})()`));});
test('Royal Cavaliers and Devoured unlock only at Stronghold level three',()=>{for(const [faction,type]of [['human','cavalier'],['horde','devoured']]){const r=game();assert.ok(r(`(()=>{const p=state.players[0],b=entity('barracks',0,500,500,true);p.faction='${faction}';p.gold=p.wood=10000;for(const level of [1,2]){state.entities[0].level=level;train(b,'${type}');if(b.queue.length)return false;}state.entities[0].level=3;train(b,'${type}');return b.queue.length===1;})()`));}});
test('deselect clears placement and selection without canceling troop orders',()=>{const r=game();assert.ok(r(`(()=>{const w=state.entities[1];selected=[w];queueTask(w,{kind:'move',x:600,y:500});const order=w.order;placement='barracks';commandMode='build';deselectAll();return selected.length===0&&placement===null&&commandMode===null&&w.order===order;})()`));});
test('opposing columns and heavy infantry reach separate destinations without blocking forever',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[];state.mountains=[];state.plateaus=[];state.rivers=[];state.blockCache={};state.ai=999;entity('base',0,100,100,true);entity('base',1,2800,2800,true);const troops=[];for(let i=0;i<12;i++){const u=entity(i%3===0?'cavalier':'melee',0,400+i%3*45,700+Math.floor(i/3)*48);queueTask(u,{kind:'move',x:1050+i%3*45,y:700+Math.floor(i/3)*48});troops.push(u);const v=entity('melee',1,1100+i%3*45,700+Math.floor(i/3)*48);queueTask(v,{kind:'move',x:450+i%3*45,y:700+Math.floor(i/3)*48});troops.push(v);}for(let i=0;i<900;i++)tick(.05);return troops.every(u=>u.order?.kind!=='move');})()`));});
test('AI raids engage nearby defending fighters instead of ignoring them for a base',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[];state.mountains=[];state.plateaus=[];state.rivers=[];const target=entity('base',0,1500,1500,true);entity('base',1,400,400,true);const defender=entity('melee',0,1200,1400),a=entity('melee',1,1180,1400);state.players[1].intel=[target];state.time=200;for(let i=0;i<8;i++)entity('melee',1,1150+i*25,1400);ai();return a.order.kind==='attack'&&a.order.target===defender;})()`));});
function openBattle(race='human'){const r=game();r(`state.entities=[];state.resources=[];state.rivers=[];state.plateaus=[];state.mountains=[];state.blockCache={};state.ai=999;state.visible.fill(1);state.seen.fill(1);state.players[0].faction='${race}';entity('base',0,100,100,true);entity('base',1,2800,2800,true);`);return r;}
test('Covenant rosters, economy, elite upgrades and hero choices form a complete third faction',()=>{const r=openBattle('covenant');assert.ok(r(`(()=>{const p=state.players[0],base=state.entities[0];p.gold=p.wood=10000;const lodge=entity('barracks',0,400,400,true);train(lodge,'cavalier');train(lodge,'devoured');if(lodge.queue.length)return false;train(lodge,'beetle');if(lodge.queue.length)return false;base.level=3;train(lodge,'beetle');train(lodge,'trapper');train(lodge,'scout');if(lodge.queue.length!==3)return false;const armory=entity('armory',0,650,400,true);upgrade(armory,'beetleTraining');if(armory.research?.key!=='beetleTraining')return false;finishResearch(armory);const beetle=entity('beetle',0,700,600);return infantryRank(beetle)===1&&names.covenant.scout==='Moth Scout'&&buildingName('base')==='Clan Citadel'&&troopOptions('forge','covenant').join()==='siege';})()`));});
test('all specialist units enforce faction ownership and Stronghold requirements',()=>{for(const race of ['human','horde','covenant']){const r=openBattle(race);assert.ok(r(`(()=>{const p=state.players[0],b=entity('barracks',0,400,400,true);p.gold=p.wood=10000;for(const type of troopOptions('barracks',p.faction).filter(t=>unitStrongholdRequirement(t)>1)){train(b,type);if(b.queue.length)return false;}state.entities[0].level=3;for(const type of Object.keys(units).filter(t=>!unitBelongs(t,p.faction))){train(b,type);if(b.queue.length)return false;}return true;})()`));}});
test('Royal Charge deals its impact once and imposes a cooldown',()=>{const r=openBattle();assert.ok(r(`(()=>{const rider=entity('cavalier',0,500,500),foe=entity('worker',1,720,500);foe.cool=999;const before=foe.hp;if(!unitAbility(rider)||unitAbility(rider))return false;for(let i=0;i<50&&rider.charge;i++)tick(.02);return rider.charge===null&&foe.hp===before-65&&foe.stunUntil>state.time&&rider.unitAbilityReady>state.time;})()`));});
test('Charge cannot cross trees or attack hidden/flying targets and stop cancels its movement',()=>{const r=openBattle();assert.ok(r(`(()=>{const rider=entity('cavalier',0,500,500),foe=entity('worker',1,720,500);state.resources=[{type:'wood',x:600,y:500,amount:100}];state.wallVersion++;if(unitAbility(rider))return false;state.resources=[];state.wallVersion++;foe.hiddenInMine=true;if(unitAbility(rider))return false;foe.hiddenInMine=false;if(!unitAbility(rider))return false;stopUnit(rider);const x=rider.x;tick(.2);return !rider.charge&&rider.x===x&&rider.order.kind==='stop';})()`));});
test('a replacement move cancels Charge while Shift preserves it until the queued move',()=>{const r=openBattle();assert.ok(r(`(()=>{const rider=entity('cavalier',0,500,500);entity('worker',1,720,500);unitAbility(rider);queueTask(rider,{kind:'move',x:800,y:650},true);if(!rider.charge||rider.tasks.length!==1)return false;queueTask(rider,{kind:'move',x:500,y:700});return !rider.charge&&rider.tasks.length===0&&rider.order.kind==='move';})()`));});
test('Devoured sweep hits multiple enemies in front, excluding allies, flyers and enemies behind',()=>{const r=openBattle('horde');assert.ok(r(`(()=>{const e=entity('devoured',0,500,500),a=entity('worker',1,550,500),b=entity('worker',1,550,540),behind=entity('worker',1,450,500),ally=entity('worker',0,550,480),flyer=entity('air',1,550,520);e.facing=0;if(!unitAbility(e)||unitAbility(e))return false;return a.hp===a.max-55&&b.hp===b.max-55&&behind.hp===behind.max&&ally.hp===ally.max&&flyer.hp===flyer.max;})()`));});
test('Shieldwardens protect nearby allies from ranged attacks but not artillery or melee',()=>{const r=openBattle();assert.ok(r(`(()=>{const ally=entity('melee',0,500,500),shield=entity('shieldwarden',0,550,500),bow=entity('ranged',1,650,500),siege=entity('siege',1,700,500),melee=entity('melee',1,600,500);if(rangedProtection(ally,bow)!==.75||rangedProtection(ally,siege)!==1||rangedProtection(ally,melee)!==1)return false;shield.x=900;return rangedProtection(ally,bow)===1;})()`));});
test('stationary medics heal injured friendly troops and engineers repair friendly artillery',()=>{const r=openBattle();assert.ok(r(`(()=>{const medic=entity('medic',0,500,500),ally=entity('melee',0,550,500),enemy=entity('worker',1,510,540),engineer=entity('engineer',0,800,500),gun=entity('siege',0,850,500);ally.hp-=50;enemy.hp-=30;gun.hp-=50;const before=ally.hp,enemyBefore=enemy.hp,gunBefore=gun.hp;supportTick(medic,1);supportTick(engineer,1);if(ally.hp!==before+6||enemy.hp!==enemyBefore||gun.hp!==gunBefore+12)return false;medic.walkUntil=state.time+2;supportTick(medic,1);return ally.hp===before+6;})()`));});
test('traps are visible destructible structures that slow only enemy ground units and expire',()=>{const r=openBattle('horde');assert.ok(r(`(()=>{const trapper=entity('trapper',0,500,500);trapper.facing=0;if(!unitAbility(trapper)||unitAbility(trapper))return false;const trap=state.entities.find(e=>e.type==='trap'),ally=entity('worker',0,trap.x,trap.y),flyer=entity('air',1,trap.x,trap.y);supportTick(trap,.1);if(trap.hp<=0)return false;const enemy=entity('worker',1,trap.x,trap.y);supportTick(trap,.1);if(trap.hp!==0||enemy.hp!==enemy.max-15||enemy.slowUntil!==state.time+4||effectiveSpeed(enemy)!==units.worker.speed*.4)return false;const empty=entity('trap',0,1000,1000,true);empty.expires=state.time-.1;supportTick(empty,.1);return empty.hp===0&&ally.hp===ally.max&&flyer.hp===flyer.max;})()`));});
test('temporary engineer barricades block paths and remove their obstruction when expired',()=>{const r=openBattle();assert.ok(r(`(()=>{const e=entity('engineer',0,500,500);if(!unitAbility(e))return false;const wall=state.entities.find(t=>t.type==='barricade'),v=state.wallVersion;if(!blockedGroundPoint(wall.x,wall.y,9)||build('barricade',800,800))return false;state.time=wall.expires;supportTick(wall,.1);return wall.hp===0&&state.wallVersion>v&&!blockedGroundPoint(wall.x,wall.y,9);})()`));});
test('scouts reveal more terrain, Survey expires, and flying scouts still require tier three',()=>{for(const race of ['human','horde','covenant']){const r=openBattle(race);assert.ok(r(`(()=>{const scout=entity('scout',0,1500,1500);fog();const x=2000,y=1500;if(visible(x,y)||visionRadius(scout)!==420||isFlying(scout)!==('${race}'!=='human'))return false;if(unitStrongholdRequirement('scout')!==('${race}'==='human'?2:3)||!unitAbility(scout))return false;fog();if(!visible(x,y))return false;state.time+=6.1;fog();return !visible(x,y)&&state.seen[Math.floor(y/CELL)*N+Math.floor(x/CELL)]===1&&visionRadius(scout)===420;})()`));}});
test('Covenant hydra burns enemies and smoke protects allies from ranged attacks without blocking artillery',()=>{const r=openBattle('covenant');assert.ok(r(`(()=>{const resin=entity('sniper',0,500,500),ally=entity('melee',0,540,500),foe=entity('ranged',1,650,500),gun=entity('siege',1,750,500);factionAttackEffect(resin,foe);if(foe.burn?.poison!==false||foe.burn.left!==4||!unitAbility(resin))return false;if(rangedProtection(ally,foe)!==.65||rangedProtection(ally,gun)!==1)return false;state.time+=6.1;return rangedProtection(ally,foe)===1;})()`));});
test('Covenant heroes retain single-choice rules and give shell, medicine, and trail abilities without talent trees',()=>{const r=openBattle('covenant');assert.ok(r(`(()=>{const h=entity('hero',0,500,500),ally=entity('melee',0,540,500);if(shieldMultiplier(ally)!==.85||!heroAbility(h)||shieldMultiplier(ally)!==.425)return false;const alchemist=entity('hero2',0,900,500);if(!heroAbility(alchemist)||!state.smoke.length)return false;const matriarch=entity('hero3',0,1200,500),runner=entity('melee',0,1240,500);if(!heroAbility(matriarch)||Math.abs(effectiveSpeed(runner)-units.melee.speed*1.1*1.3)>.001)return false;return heroTree('covenant','hero').length===0&&heroAuraText(alchemist).includes('1 health/s');})()`));});
test('Bogbreaker knocks ground units aside but cannot push them through trees',()=>{const r=openBattle('horde');assert.ok(r(`(()=>{const troll=entity('bogbreaker',0,500,500),foe=entity('worker',1,530,500);factionAttackEffect(troll,foe);if(foe.x!==552||foe.stunUntil<=state.time)return false;state.resources=[{type:'wood',x:574,y:500,amount:100}];state.wallVersion++;factionAttackEffect(troll,foe);return foe.x===552;})()`));});
test('Burrow Ambush waits before eruption, excludes flyers, and can be canceled by a move',()=>{const r=openBattle('covenant');assert.ok(r(`(()=>{const burrower=entity('siege',0,500,500),foe=entity('worker',1,540,500),flyer=entity('air',1,540,530);if(!unitAbility(burrower))return false;supportTick(burrower,1);if(foe.hp!==foe.max)return false;state.time+=2.6;supportTick(burrower,.1);if(foe.hp!==foe.max-60||flyer.hp!==flyer.max)return false;state.time=burrower.unitAbilityReady;unitAbility(burrower);queueTask(burrower,{kind:'move',x:800,y:500});return !burrower.burrowUntil&&burrower.order.kind==='move';})()`));});

test('animation atlases load on demand and reuse the same image until unused',()=>{const c=vm.createContext({Image:class{},Math});vm.runInContext(fs.readFileSync(require.resolve('../frontier-art.js'),'utf8'),c);assert.equal(vm.runInContext('Object.keys(frontierSheets).length',c),0);assert.ok(vm.runInContext("getFrontierSheet('cov-moth')===getFrontierSheet('cov-moth')&&Object.keys(frontierSheets).length===1",c));});
test('Covenant portraits use small faction-specific images for core and elite units',()=>{const r=game();assert.match(r("unitPicture('worker','covenant')"),/portrait-cov-worker/);assert.match(r("unitPicture('beetle','covenant')"),/portrait-cov-beetle/);assert.match(r("unitPicture('scout','horde')"),/portrait-carrion/);});
test('AI scouts expand reconnaissance for abilities and flee nearby fighters instead of charging into battle',()=>{const r=openBattle();assert.ok(r(`(()=>{state.players[1].faction='human';const cavalry=entity('cavalier',1,800,800),target=entity('worker',0,1100,800);if(unitAbility(cavalry,true))return false;const scout=entity('scout',1,850,800);if(!unitAbility(cavalry,true))return false;const defender=entity('melee',0,900,800);ai();return scout.order?.kind==='move'&&scout.order.x<scout.x;})()`));});

test('destroyed field barricades invalidate ground routing',()=>{const r=openBattle();assert.ok(r(`(()=>{const e=entity('engineer',0,500,500);unitAbility(e);const wall=state.entities.find(t=>t.type==='barricade'),v=state.wallVersion;wall.hp=0;tick(.1);return state.wallVersion>v&&!blockedGroundPoint(wall.x,wall.y,9);})()`));});

test('Covenant vipers poison troops but cannot poison buildings',()=>{const r=openBattle('covenant');assert.ok(r(`(()=>{const snake=entity('ranged',0,500,500),foe=entity('melee',1,550,500),base=entity('base',1,700,500,true);factionAttackEffect(snake,foe);factionAttackEffect(snake,base);return foe.burn.poison===true&&foe.burn.left===3&&!base.burn&&names.covenant.melee==='Ancient Treant'&&names.covenant.sniper==='Fire Hydra';})()`));});

test('Covenant creature attacks use venom and fire projectiles instead of arrows',()=>{const r=openBattle('covenant');assert.ok(r(`(()=>{const v=entity('ranged',0,500,500),h=entity('sniper',0,500,700),a=entity('melee',1,600,500),b=entity('melee',1,600,700);v.order={kind:'attack',target:a};h.order={kind:'attack',target:b};a.order=b.order={kind:'stop'};state.players[0].fire=1;tick(.1);return v.shot.poison&&!v.shot.fire&&a.burn.poison&&a.burn.left>3.8&&h.shot.fire&&!h.shot.poison&&!b.burn.poison;})()`));});
test('Sky Skitterer is Covenant-only, tier three and trains at the Wing Pavilion',()=>{const r=openBattle('covenant');assert.ok(r(`(()=>{const base=state.entities.find(e=>e.type==='base'&&e.owner===0),p=state.players[0],roost=entity('roost',0,400,400,true);p.gold=p.wood=10000;base.level=2;train(roost,'air3');if(roost.queue.length)return false;base.level=3;roost.rally={x:700,y:700};train(roost,'air3');if(roost.queue[0].type!=='air3'||!troopOptions('roost','covenant').includes('air3')||troopOptions('roost','human').includes('air3'))return false;tick(27.625);const u=state.entities.find(e=>e.type==='air3');return u&&isFlying(u)&&u.order.kind==='move'&&unitAppearance(u.type,'covenant')==='cov-centipede';})()`));const h=openBattle('human');assert.equal(h(`(()=>{state.entities[0].level=3;const roost=entity('roost',0,400,400,true);train(roost,'air3');return roost.queue.length;})()`),0);});
test('Stag Wasps require Venom Stingers research for poison and update existing/new stingers',()=>{const r=openBattle('covenant');assert.ok(r(`(()=>{const base=state.entities.find(e=>e.owner===0&&e.type==='base'),p=state.players[0],roost=entity('roost',0,400,400,true),wasp=entity('air2',0,500,500),target=entity('melee',1,600,500);base.level=3;p.gold=p.wood=10000;target.order={kind:'stop'};wasp.order={kind:'attack',target};tick(.01);if(target.burn||wasp.shot.poison||wasp.venomStinger)return false;wasp.order={kind:'stop'};upgrade(roost,'waspVenom');if(roost.research.key!=='waspVenom'||roost.research.gold!==160||roost.research.wood!==120||roost.research.total!==31.25)return false;tick(31.375);if(p.waspVenom!==1||!wasp.venomStinger||unitAppearance('air2','covenant')!=='cov-wasp-venom')return false;const fresh=entity('air2',0,510,500);if(!fresh.venomStinger)return false;fresh.order={kind:'stop'};wasp.cool=0;wasp.order={kind:'attack',target};tick(.01);if(!target.burn?.poison||!wasp.shot.poison)return false;wasp.order={kind:'stop'};const hp=target.hp;tick(1);if(Math.abs(hp-target.hp-5)>.0001)return false;upgrade(roost,'waspVenom');return !roost.research&&p.waspVenom===1;})()`));});
test('Venom research obeys faction/building/tier restrictions and can be refunded',()=>{const r=openBattle('covenant');assert.ok(r(`(()=>{const p=state.players[0],base=state.entities.find(e=>e.owner===0&&e.type==='base'),roost=entity('roost',0,400,400,true),armory=entity('armory',0,700,400,true);p.gold=p.wood=1000;base.level=2;upgrade(roost,'waspVenom');upgrade(armory,'waspVenom');if(roost.research||armory.research)return false;base.level=3;upgrade(roost,'waspVenom');if(!cancelProduction(roost.id,'research')||p.gold!==1000||p.wood!==1000||p.waspVenom)return false;p.faction='human';upgrade(roost,'waspVenom');return !roost.research;})()`));});
test('venom stingers do not poison buildings and refreshed poison has one damage rate',()=>{const r=openBattle('covenant');assert.ok(r(`(()=>{state.players[0].waspVenom=1;const w=entity('air2',0,500,500),b=entity('barracks',1,600,500,true);w.order={kind:'attack',target:b};tick(.01);if(b.burn)return false;const target=entity('melee',1,600,700),a=entity('air2',0,500,700),c=entity('air2',0,510,700);target.order={kind:'stop'};a.order=c.order={kind:'attack',target};tick(.01);a.order=c.order={kind:'stop'};const hp=target.hp;tick(.5);return target.burn.poison&&Math.abs(hp-target.hp-2.5)<.0001;})()`));});

test('zoom preserves camera center, maps clicks to world space and stays bounded',()=>{const r=game();assert.ok(r(`(()=>{cam={x:700,y:600};const cx=cam.x+viewport.width/2,cy=cam.y+viewport.height/2;changeBattlefieldZoom(-.15);if(Math.abs(cam.x+viewport.width/2-cx)>.001||Math.abs(cam.y+viewport.height/2-cy)>.001||viewport.width!==1200/.85)return false;const p=point({clientX:600,clientY:325});if(Math.abs(p.x-cx)>.01)return false;for(let i=0;i<20;i++)changeBattlefieldZoom(-.15);if(battlefieldZoom!==.55)return false;for(let i=0;i<20;i++)changeBattlefieldZoom(.15);return battlefieldZoom===1&&viewport.width===1200;})()`));});
test('exhausted trees fall once, release obstacles and disappear after the animation',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[];state.mountains=[];state.rivers=[];state.plateaus=[];state.ai=999;entity('base',0,100,100,true);entity('base',1,2800,2800,true);const t={type:'wood',x:500,y:500,amount:.15},w=entity('worker',0,480,500);state.resources=[t];w.order={kind:'gather',target:t};const version=state.wallVersion;tick(.1);if(t.amount!==0||t.fallAt!==state.time||!resourceStillVisible(t)||state.wallVersion!==version+1||w.order.kind!=='deliver')return false;tick(.7);if(!state.resources.includes(t)||treeFallProgress(t)<=0)return false;tick(.71);return !state.resources.includes(t)&&!resourceStillVisible(t)&&w.cargoWood===.15;})()`));});
test('Covenant golem throws rocks and earlier flying reductions stack with the global size reduction',()=>{const r=game();assert.ok(r(`(()=>{state.players[0].faction='covenant';state.entities=[];state.resources=[];state.mountains=[];state.rivers=[];state.plateaus=[];state.ai=999;entity('base',0,100,100,true);entity('base',1,2800,2800,true);const g=entity('hero',0,500,500),enemy=entity('worker',1,550,500);enemy.cool=999;g.order={kind:'attack',target:enemy};fog();tick(.01);return names.covenant.hero==='Granite Guardian'&&g.shot.rock&&!g.shot.web&&Math.abs(unitVisualScale(entity('air2',0,500,500))-.455175)<1e-9&&Math.abs(unitVisualScale(entity('air3',0,500,500))-.4226625)<1e-9&&Math.abs(unitVisualScale(entity('air2',1,500,500))-.455175)<1e-9;})()`));});
test('Sticky Webs requires the Covenant Burrow Den at tier two, queues once and refunds cancellation',()=>{const r=game();assert.ok(r(`(()=>{const p=state.players[0];p.faction='covenant';p.gold=p.wood=2000;state.ai=999;const b=entity('forge',0,500,500,true),base=state.entities[0];upgrade(b,'stickyWebs');if(b.research)return false;base.level=2;const gold=p.gold,wood=p.wood;upgrade(b,'stickyWebs');if(b.research?.key!=='stickyWebs'||b.research.left!==37.5||p.gold!==gold-180||p.wood!==wood-140)return false;upgrade(b,'stickyWebs');if(b.researchQueue?.length)return false;cancelProduction(b.id,'research');if(p.gold!==gold||p.wood!==wood)return false;upgrade(b,'stickyWebs');finishResearch(b);return p.stickyWebs===1;})()`));});
test('Burrowbreaker webs slow living targets only after research, refresh without stacking and expire',()=>{const r=game();assert.ok(r(`(()=>{state.players[0].faction='covenant';state.entities=[];state.resources=[];state.mountains=[];state.rivers=[];state.plateaus=[];state.ai=999;entity('base',0,100,100,true);entity('base',1,2800,2800,true);const s=entity('siege',0,500,500),target=entity('melee',1,600,500);target.max=target.hp=5000;target.order={kind:'stop'};s.order={kind:'attack',target};fog();tick(.01);if(!s.shot.web||target.webSlowUntil)return false;state.players[0].stickyWebs=1;s.cool=0;tick(.01);if(effectiveSpeed(target)!==units.melee.speed*.5)return false;s.cool=0;tick(.1);if(effectiveSpeed(target)!==units.melee.speed*.5)return false;s.order={kind:'stop'};tick(4.01);return effectiveSpeed(target)===units.melee.speed;})()`));});

test('zoom preserves the full quality drawing-buffer budget on a 1x display',()=>{const r=game();assert.equal(r('viewport.scale'),1.5);const width=r('canvas.width');r('changeBattlefieldZoom(-.45)');assert.equal(r('battlefieldZoom'),.55);assert.equal(r('canvas.width'),width);assert.equal(r('viewport.scale'),1.5*.55);});
test('Verdant wind elemental fires gusts and places wind traps without changing Dominion traps',()=>{const r=openBattle('covenant');assert.ok(r(`(()=>{state.resources=[];state.mountains=[];state.rivers=[];state.plateaus=[];state.ai=999;const wind=entity('trapper',0,500,500),foe=entity('worker',1,600,500);foe.order={kind:'stop'};wind.order={kind:'attack',target:foe};tick(.01);if(!wind.shot?.wind||wind.shot.fire||wind.shot.poison||unitAppearance('trapper','covenant')!=='cov-weaver'||names.covenant.trapper!=='Wind Elemental')return false;if(abilityDefinition(wind).name!=='Wind Trap'||!unitAbility(wind))return false;const trap=state.entities.find(e=>e.owner===0&&e.type==='trap');if(!trap||buildingName('trap',0)!=='Wind Trap')return false;foe.x=trap.x;foe.y=trap.y;supportTick(trap,.01);return trap.hp===0&&foe.slowUntil===state.time+4&&state.effects.some(e=>e.kind==='wind')&&abilityDefinition(entity('trapper',1,1400,1400)).name==='Lay Trap'&&buildingName('trap',1)==='Resin Trap';})()`));});

test('attack-move fights in range, resumes its destination and accepts an immediate replacement move',()=>{const r=openBattle();assert.ok(r(`(()=>{const fighter=entity('ranged',0,500,500),enemy=entity('melee',1,620,500);enemy.order={kind:'stop'};selected=[fighter];commandMode='attackMove';issueCommand({x:900,y:500});tick(.01);if(fighter.order.kind!=='attackMove'||enemy.hp===enemy.max||fighter.x!==500)return false;enemy.hp=0;tick(.1);if(fighter.x<=500||fighter.order.x!==900)return false;queueTask(fighter,{kind:'move',x:300,y:500});const x=fighter.x;tick(.1);return fighter.order.kind==='move'&&fighter.x<x&&!fighter.tasks.length;})()`));});
test('attack-move preserves Shift waypoints and workers use ordinary movement',()=>{const r=openBattle();assert.ok(r(`(()=>{const fighter=entity('melee',0,500,500),worker=entity('worker',0,500,550);selected=[fighter,worker];commandMode='attackMove';issueCommand({x:700,y:500});if(fighter.order.kind!=='attackMove'||worker.order.kind!=='move')return false;commandMode='attackMove';issueCommand({x:900,y:500},true);return fighter.tasks[0].kind==='attackMove'&&fighter.order.x<900;})()`));});
test('all fighters selection excludes workers, buildings, dead units and enemy troops',()=>{const r=openBattle();assert.ok(r(`(()=>{const a=entity('melee',0,500,500),b=entity('air2',0,3000,3000);entity('worker',0,550,500);entity('medic',0,600,500);entity('melee',1,700,500);entity('siege',0,800,500).hp=0;selectAllFighters();return selected.length===2&&selected.includes(a)&&selected.includes(b);})()`));});
test('AI funds actual stronghold cost below the old saving threshold and prioritizes siege and sky buildings',()=>{const r=openBattle();assert.ok(r(`(()=>{const p=state.players[1],base=state.entities.find(e=>e.owner===1&&e.type==='base');p.gold=500;p.wood=350;entity('barracks',1,base.x-150,base.y,true);for(let i=0;i<3;i++)entity('melee',1,base.x-100-i*35,base.y-120);ai();if(base.research?.key!=='stronghold')return false;finishResearch(base);p.gold=p.wood=10000;entity('worker',1,base.x-100,base.y);ai();const forge=state.entities.find(e=>e.owner===1&&e.type==='forge');if(!forge)return false;forge.construction=null;base.level=3;ai();const roost=state.entities.find(e=>e.owner===1&&e.type==='roost');if(!roost||forge.queue[0]?.type!=='siege')return false;roost.construction=null;ai();return roost.queue.some(q=>['air','air2','air3'].includes(q.type));})()`));});

test('wall price is halved exactly and gates can be built on the wall grid',()=>{const r=openBattle();assert.ok(r(`(()=>{state.resources=[];state.mountains=[];state.plateaus=[];state.rivers=[];state.visible.fill(1);const w=entity('worker',0,450,550);selected=[w];const g=state.players[0].gold,l=state.players[0].wood;if(!build('wall',600,600))return false;if(state.players[0].gold!==g-7.5||state.players[0].wood!==l-17.5)return false;return build('gate',632,600)&&state.entities.some(e=>e.type==='gate'&&e.x===624&&e.y===592&&e.construction);})()`));});
test('opening a converted wall gate clears collision and routes; occupied gates cannot close',()=>{const r=openBattle();assert.ok(r(`(()=>{state.resources=[];state.mountains=[];state.plateaus=[];state.rivers=[];const w=entity('wall',0,624,592,true),u=entity('melee',0,560,592);w.hp=w.max*.5;if(!convertWallToGate(w)||w.type!=='gate'||w.hp!==w.max*.5)return false;const version=state.wallVersion;if(clearWallLine(u,680,592))return false;if(!toggleGate(w)||state.wallVersion!==version+1||!clearWallLine(u,680,592))return false;u.x=w.x;u.y=w.y;if(toggleGate(w)!==false||!w.gateOpen)return false;u.x=560;return toggleGate(w)&&!w.gateOpen&&!clearWallLine(u,680,592);})()`));});
test('all units are visually smaller and the human phoenix has an additional 25 percent reduction',()=>{const r=game();assert.equal(r("unitVisualScale(entity('worker',0,500,500))"),.65025);assert(Math.abs(r("unitVisualScale(entity('air2',0,500,500))")-.4876875)<1e-9);assert(Math.abs(r("unitVisualScale(entity('air2',1,500,500))")-.455175)<1e-9);});

test('supply houses count only when complete and living, up to 200',()=>{const r=game();assert.equal(r('supplyCap(0)'),20);assert.equal(r(`(()=>{const h=entity('house',0,400,500,true);h.construction={left:2,total:2};return supplyCap(0);})()`),20);assert.equal(r("delete state.entities.at(-1).construction;supplyCap(0)"),30);assert.equal(r("state.entities.at(-1).hp=0;supplyCap(0)"),20);assert.equal(r("for(let i=0;i<30;i++)entity('house',0,500+i*60,500,true);supplyCap(0)"),200);});
test('training reserves supply across buildings and never charges a blocked order',()=>{const r=game();assert.ok(r(`(()=>{state.ai=999;const p=state.players[0];p.gold=p.wood=10000;const a=entity('barracks',0,600,500,true),b=entity('barracks',0,750,500,true),c=entity('barracks',0,900,500,true);for(let i=0;i<5;i++){train(a,'melee');train(b,'ranged');train(c,'sniper');}train(state.entities[0],'worker');const gold=p.gold,wood=p.wood;train(state.entities[0],'worker');return supplyUsed(0)===20&&state.entities[0].queue.length===1&&p.gold===gold&&p.wood===wood;})()`));});
test('cancelling training frees its reserved supply slot',()=>{const r=game();assert.ok(r(`(()=>{const b=state.entities[0],before=supplyUsed(0);train(b,'worker');if(supplyUsed(0)!==before+1)return false;cancelProduction(b.id,String(b.queue[0].id));return supplyUsed(0)===before;})()`));});
test('destroyed housing pauses completed training until capacity returns',()=>{const r=game();assert.ok(r(`(()=>{state.ai=999;state.resources=[];state.mountains=[];state.rivers=[];state.plateaus=[];const b=state.entities[0],h=entity('house',0,800,800,true);for(let i=0;i<16;i++){const u=entity('melee',0,1300+i*35,1300);u.order={kind:'stop'};}train(b,'worker');if(!b.queue.length)return false;h.hp=0;tick(20);if(!b.queue[0]?.waitingForSupply||supplyUsed(0,false)!==20)return false;entity('house',0,800,800,true);tick(.1);return b.queue.length===0&&supplyUsed(0,false)===21;})()`));});
test('AI prioritizes an affordable supply house over reserving resources for tech near its cap',()=>{const r=game();assert.ok(r(`(()=>{state.resources=[];state.mountains=[];state.rivers=[];state.plateaus=[];const base=state.entities.find(e=>e.owner===1&&e.type==='base'),p=state.players[1];p.gold=140;p.wood=100;entity('barracks',1,base.x+250,base.y,true);for(let i=0;i<12;i++)entity('melee',1,base.x+400+i*30,base.y);ai();return state.entities.some(e=>e.owner===1&&e.type==='house'&&e.construction);})()`));});

test('Gold Mine construction is gated at Stronghold four and pays its full price',()=>{const r=game();assert.ok(r(`(()=>{state.ai=999;state.resources=[];state.mountains=[];state.rivers=[];state.plateaus=[];state.visible.fill(1);const base=state.entities[0],worker=state.entities[1];selected=[worker];state.players[0].gold=1000;state.players[0].wood=1000;base.level=3;if(build('goldmine',500,500))return false;if(state.players[0].gold!==1000)return false;base.level=4;if(!build('goldmine',500,500))return false;const mine=state.entities.at(-1);return mine.type==='goldmine'&&mine.construction.total===75&&state.players[0].gold===650&&state.players[0].wood===750;})()`));});
test('completed Gold Mines generate credited gold without resources or workers, stopping on death',()=>{const r=game();assert.ok(r(`(()=>{state.ai=999;state.resources=[];state.entities=state.entities.filter(e=>e.building);const mine=entity('goldmine',0,700,700,true),p=state.players[0],before=p.gold;mine.construction={total:75,left:75};tick(2);if(p.gold!==before)return false;delete mine.construction;tick(3.5);if(p.gold!==before+3.5||matchStats(0).goldGained!==3.5)return false;mine.hp=0;tick(2);return p.gold===before+3.5;})()`));});
test('mine outcrops remain behind accessible entrances and block ground movement',()=>{const r=game();assert.ok(r(`(()=>{const mines=state.resources.filter(r=>r.type==='gold'&&!r.noOutcrop);if(!mines.length)return false;for(const mine of mines){const rocks=goldOutcropRocks(mine);if(rocks.length!==3||rocks.some(o=>riverAt(o.x,o.y,o.half)))return false;if(rocks.some(o=>Math.abs(mine.x-o.x)<o.half+23&&Math.abs(mine.y-o.y)<o.half+23))return false;}const mine=mines[0],rock=goldOutcropRocks(mine)[0],worker=state.entities[1];return blockedGroundPoint(rock.x,rock.y,worker.size)&&!!resourceApproach(worker,mine);})()`));});

test('smaller mountain ridges leave unit-clear passages and avoid bridge and ramp approaches',()=>{const r=game();assert.ok(r(`(()=>{for(const key of Object.keys(mapDefinitions)){const peaks=makeMountains(key);if(!peaks.length||peaks.some(p=>p.half>40))return false;for(const a of peaks)for(const b of peaks)if(a!==b&&Math.abs(a.x-b.x)<a.half+b.half+32&&Math.abs(a.y-b.y)<a.half+b.half+32)return false;for(const p of makePlateaus(key))if(peaks.some(m=>Math.abs(m.x-p.rampX)<m.half+96&&Math.abs(m.y-(p.y+p.h))<m.half+112))return false;}return true;})()`));});
test('ridge central crossings remain clear after natural mines and forest placement',()=>{const r=game();assert.ok(r(`(()=>{for(const key of Object.keys(mapDefinitions)){state.map=key;state.mountains=makeMountains(key);state.plateaus=makePlateaus(key);state.rivers=makeRivers(key);state.resources=[];populateResources(spawnLocations(()=>.999));if(state.resources.some(t=>mountainPassageAt(t.x,t.y,t.type==='gold'?40:28)))return false;if(mineRockObstacles().some(o=>mountainPassageAt(o.x,o.y,o.half+12)))return false;}return true;})()`));});

test('one standard bearer is reserved across Strongholds and auras switch exclusively with gathering gated at tier three',()=>{const r=game();assert.ok(r(`(()=>{const b=state.entities[0];state.players[0].gold=state.players[0].wood=5000;if(troopOptions('base','horde').filter(t=>t.startsWith('banner')).length!==1)return false;train(b,'bannerDamage');train(b,'bannerDamage');if(b.queue.length!==1)return false;const other=entity('base',0,1000,1000,true);train(other,'bannerDamage');if(other.queue.length)return false;const bearer=entity('bannerDamage',0,b.x,b.y);if(setBannerAura(bearer,'bannerHarvest'))return false;if(!setBannerAura(bearer,'bannerHealth')||bannerAura(bearer,'bannerDamage')!==0||bannerAura(bearer,'bannerHealth')!==.05)return false;b.level=3;if(!setBannerAura(bearer,'bannerHarvest')||bannerAura(bearer,'bannerHealth')!==0)return false;upgrade(b,'bannerDamageAura');upgrade(b,'bannerDamageAura');upgrade(b,'bannerDamageAura');if(researchJobs(b).length!==2)return false;finishResearch(b);finishResearch(b);return state.players[0].bannerDamageAura===2;})()`));});
test('standard aura respects range, ownership, death and non-stacking',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];const u=entity('melee',0,500,500),a=entity('bannerDamage',0,520,500),b=entity('bannerDamage',0,520,520),enemy=entity('melee',1,500,500);if(bannerAura(u,'bannerDamage')!==.05||bannerAura(enemy,'bannerDamage')!==0)return false;state.players[0].bannerDamageAura=2;if(Math.abs(bannerAura(u,'bannerDamage')-.15)>1e-9)return false;a.hp=b.hp=0;return bannerAura(u,'bannerDamage')===0;})()`));});
test('health standard buffs nearby units and buildings without healing on repeated entry or exit',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];const u=entity('melee',0,500,500),b=entity('tower',0,510,500,true),a=entity('bannerHealth',0,520,500);u.hp=u.max/2;const base=u.max,buildingBase=b.max;refreshBannerHealth();if(Math.abs(u.max-base*1.05)>.001||Math.abs(b.max-buildingBase*1.05)>.001||Math.abs(u.hp/u.max-.5)>.001)return false;for(let i=0;i<5;i++){a.x=1000;refreshBannerHealth();a.x=520;refreshBannerHealth();}a.hp=0;refreshBannerHealth();return Math.abs(u.hp-base/2)<.001&&u.max===base;})()`));});
test('harvest standard increases nearby worker gathering and gold works income only from tier three',()=>{const r=game();assert.ok(r(`(()=>{state.ai=999;state.mountains=[];state.rivers=[];state.plateaus=[];state.resources=[];state.entities=[];const base=entity('base',0,200,200,true),w=entity('worker',0,500,500),a=entity('bannerHarvest',0,510,500),g=entity('goldmine',0,600,500,true),tree={type:'wood',x:520,y:500,amount:1000};state.resources=[tree];if(bannerAura(w,'bannerHarvest')!==0)return false;base.level=3;state.players[0].bannerHarvestAura=2;w.order={kind:'gather',target:tree};const gold=state.players[0].gold;tick(1);return Math.abs(w.cargoWood-GATHER_RATE*1.15)<.001&&Math.abs(state.players[0].gold-gold-1.15)<.001;})()`));});
test('Dominion towers emit spear projectiles from their raised throwing platform',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.players[0].faction='horde';const tower=entity('tower',0,500,500,true),target=entity('melee',1,550,500);state.visible.fill(1);defenseAttack(tower);return tower.shot.spear===true&&tower.shot.fromHeight===65&&tower.action.kind==='attack'&&target.hp<target.max;})()`));});
test('war standards increase actual attack damage and stop buffing outside range',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[];state.mountains=[];state.rivers=[];state.plateaus=[];state.ai=999;state.visible.fill(1);const a=entity('melee',0,500,500),t=entity('melee',1,520,500),b=entity('bannerDamage',0,1000,500);t.cool=999;tick(.01);const normal=t.max-t.hp;t.hp=t.max;a.cool=0;b.x=510;tick(.01);return Math.abs((t.max-t.hp)/normal-1.05)<1e-6;})()`));});

test('admin units and queued research complete in one second and idle collector selection excludes resource work',()=>{const r=game();assert.ok(r(`(()=>{state.players[0].gold=state.players[0].wood=5000;const b=state.entities[0];state.adminResources=true;train(b,'worker');upgrade(b,'stronghold');if(b.queue[0].total!==1||b.research.total!==1)return false;const workers=state.entities.filter(e=>e.type==='worker'&&e.owner===0);workers[0].order={kind:'gather',target:state.resources[0]};workers[1].order={kind:'deliver'};selectIdleCollectors();return selected.every(e=>e.type==='worker'&&!['gather','deliver'].includes(e.order?.kind))&&!selected.includes(workers[0])&&!selected.includes(workers[1]);})()`));});
test('spatial combat search matches nearest visible enemy and ignores allies and dead troops',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.visible.fill(1);combatIndex=null;const u=entity('melee',0,500,500),far=entity('melee',1,700,500),near=entity('melee',1,530,500);entity('melee',0,501,500);const dead=entity('melee',1,502,500);dead.hp=0;if(nearestCombatTarget(u)!==near)return false;near.hiddenInMine=true;return nearestCombatTarget(u)===far;})()`));});
test('completed standard consumes the one-per-game slot even after death while canceled queues release it',()=>{const r=game();assert.ok(r(`(()=>{const b=state.entities[0];state.adminResources=true;state.ai=999;state.resources=[];state.mountains=[];state.rivers=[];state.plateaus=[];train(b,'bannerDamage');if(!cancelProduction(b.id,String(b.queue[0].id))||bannerReserved(0))return false;train(b,'bannerDamage');tick(1.01);const bearer=state.entities.find(e=>e.owner===0&&isBannerBearer(e));if(!bearer||!state.players[0].bannerTrained)return false;bearer.hp=0;train(b,'bannerDamage');return b.queue.length===0&&bannerReserved(0);})()`));});

test('Dominion tower fire spears require completed research and burn units, never friendly troops or buildings',()=>{const r=game();assert.ok(r(`(()=>{state.entities=[];state.resources=[];state.mountains=[];state.rivers=[];state.plateaus=[];state.players[0].faction='horde';state.players[1].faction='human';state.players[0].gold=state.players[0].wood=5000;const tower=entity('tower',0,500,500,true),enemy=entity('worker',1,600,500);state.visible.fill(1);defenseAttack(tower);if(enemy.burn)return false;upgrade(tower,'towerFire');if(tower.research?.key!=='towerFire')return false;finishResearch(tower);tower.cool=0;defenseAttack(tower);if(!tower.shot.spear||!tower.shot.fire||enemy.burn?.left!==4||enemy.burn.owner!==0)return false;upgrade(tower,'towerFire');if(tower.research)return false;const other=entity('tower',1,700,500,true);upgrade(other,'towerFire');return !other.research;})()`));});
